(gen_random_uuid(), 'abu-dhabi', 'phrase', 'أريد هذا من فضلك · urīdu hādhā min faḍlik', '“urīdu hādhā min faḍlik” means “I would like this, please.” Point only after saying the phrase so the request stays clear and courteous.', 'Pronunciation: oo-ree-doo haa-tha min fad-lik', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "I would like this, please", "fact_review": "pending_human_fact_review", "intent": "ordering", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "أريد هذا من فضلك", "pronunciation": "oo-ree-doo haa-tha min fad-lik", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "urīdu hādhā min faḍlik", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Point only after saying the phrase so the request stays clear and courteous.", "usage_context": "Point only after saying the phrase so the request stays clear and courteous.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/arabic.php', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'phrase', 'أين ...؟ · ayna ...?', '“ayna ...?” means “Where is ...?” Place a destination after ayna, or show the written name while asking.', 'Pronunciation: ay-na', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Where is ...?", "fact_review": "pending_human_fact_review", "intent": "navigation", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "أين ...؟", "pronunciation": "ay-na", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "ayna ...?", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Place a destination after ayna, or show the written name while asking.", "usage_context": "Place a destination after ayna, or show the written name while asking.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/arabic.php', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'phrase', 'شكراً · shukran', '“shukran” means “Thank you.” Use it after help, service, or directions.', 'Pronunciation: shook-ran', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Thank you", "fact_review": "pending_human_fact_review", "intent": "thanks", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "شكراً", "pronunciation": "shook-ran", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "shukran", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it after help, service, or directions.", "usage_context": "Use it after help, service, or directions.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/arabic.php', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'phrase', 'لو سمحت · law samaḥt', '“law samaḥt” means “Excuse me; if you please.” Use it to get attention or ask for help without calling across a room.', 'Pronunciation: law sa-maht', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Excuse me; if you please", "fact_review": "pending_human_fact_review", "intent": "excuse", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "لو سمحت", "pronunciation": "law sa-maht", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "law samaḥt", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it to get attention or ask for help without calling across a room.", "usage_context": "Use it to get attention or ask for help without calling across a room.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/arabic.php', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'phrase', 'مرحبا · Marḥaban', '“Marḥaban” is an Arabic “hello” or “welcome” that works as a friendly greeting. Abu Dhabi is exceptionally multilingual, so offer it warmly, avoid assuming anyone’s nationality or first language, and switch languages graciously.', 'Pronunciation: marḥaban', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Hello; welcome.", "fact_review": "pending_human_fact_review", "intent": "greeting", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "مرحبا", "pronunciation": "marḥaban", "recheck_date": "2027-01-25", "register": "friendly-polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "marḥaban", "source_publisher": "visitdubai.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Offer a friendly greeting on arrival or when meeting someone.", "usage_context": "Useful across visitor settings; Abu Dhabi is multilingual, so do not infer language from appearance.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.visitdubai.com/travel-trade/explore-dubai/local-culture-and-heritage', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'phrase', 'من فضلك · min faḍlak / min faḍlik', '“min faḍlak / min faḍlik” means “Please.” Add it to a request; the ending traditionally varies with the person addressed.', 'Pronunciation: min fad-lak / min fad-lik', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Please", "fact_review": "pending_human_fact_review", "intent": "please", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "من فضلك", "pronunciation": "min fad-lak / min fad-lik", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "min faḍlak / min faḍlik", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Add it to a request; the ending traditionally varies with the person addressed.", "usage_context": "Add it to a request; the ending traditionally varies with the person addressed.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/arabic.php', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'drink', 'Gahwa: coffee as cultural practice', 'Emirati gahwa is lightly roasted Arabic coffee flavored with spices such as cardamom and served in small cups. It is nonalcoholic but caffeinated; Qasr Al Hosn interprets preparation, serving, and etiquette as connected heritage.', null, '☕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Contains caffeine; spice blend varies.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Emirati hospitality and heritage interpretation", "source_publisher": "visitabudhabi.ae", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitabudhabi.ae/en/plan-your-trip/article-hub/10-coffee-shops-to-visit-in-abu-dhabi', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'drink', 'Traditional tea at Qaryat Al Torath', 'Kitchens at Qaryat Al Torath Heritage Village serve traditional tea alongside Emirati foods and sweets. Tea is nonalcoholic and usually caffeinated; ask what blend, milk, and sweetener are used rather than assuming one fixed recipe.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Caffeine, milk, and sweetener depend on the preparation.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Qaryat Al Torath Heritage Village in Al Ain", "source_publisher": "visitabudhabi.ae", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitabudhabi.ae/en/things-to-do/culture/heritage/qaryat-altorath-heritage-village', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'etiquette', 'Ask before photographing at Mina Markets', 'Mina''s fish, produce, and date markets are working spaces. Frame goods from clear walkways; before centering a vendor, customer, or close-up task, ask plainly and accept a refusal without negotiation.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "photography and shared-space courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Emirati heritage sites", "source_publisher": "visitabudhabi.ae", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitabudhabi.ae/en/things-to-do/shopping/mina-markets', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'etiquette', 'Ask the counter''s rhythm at Mina Markets', 'At Mina Markets, fish, produce, dates, and household goods may use different checkout rhythms. Confirm the quantity, total, and accepted payment method before the seller packs the purchase.', null, '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "ordering, queue, and payment courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Mina Markets", "source_publisher": "visitabudhabi.ae", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitabudhabi.ae/en/things-to-do/shopping/mina-markets', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'etiquette', 'Let the other person initiate the handshake', 'Greeting customs vary, especially across genders and degrees of familiarity. Smile, greet verbally, and wait for the other person to offer a hand; this leaves room for religious preference, personal boundaries, and international norms.', null, '🤝', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "consent-led social courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Introductions and professional or social greetings", "source_publisher": "visitabudhabi.ae", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitabudhabi.ae/en/abu-dhabi-convention-and-exhibition-bureau/business-culture/greeting', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'etiquette', 'Make space on Abu Dhabi public buses', 'On Abu Dhabi buses, board through the indicated door, keep priority areas available, and have the current fare method ready before stepping into the aisle.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "transit and queue courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Abu Dhabi public buses", "source_publisher": "admobility.gov.ae", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://admobility.gov.ae/en/pb-bus-service', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'abu-dhabi', 'market', 'Mina Markets: the city faces the sea', 'Mina Zayed’s fish, fruit, vegetable, carpet, and household markets show Abu Dhabi’s maritime and trading life. Keep clear of unloading and sales, ask before photographing workers, and handle fresh products only with vendor permission.', null, '🐟', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "fact_review": "pending_human_fact_review", "mutable_details_excluded": true, "operation_recheck": "2027-01-25", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Working fish, produce, and goods markets", "source_publisher": "visitabudhabi.ae", "source_title": "Official destination market guide", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitabudhabi.ae/en/things-to-do/shopping/mina-markets', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'accra', 'phrase', 'Medaase', 'Medaase (meh-DAH-see) means "thank you" in Twi. Use it after a greeting, a purchase, or any small kindness; in Accra, beginning with a greeting before moving to your request matters as much as the words that follow.', 'Pronunciation: meh-DAH-see', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Thank you", "language": "Twi", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "meh-DAH-see", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "meh-DAH-see", "usage": "Medaase (meh-DAH-see) means \"thank you\" in Twi. Use it after a greeting, a purchase, or any small kindness; in Accra, beginning with a greeting before moving to your request matters as much as the words that follow.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://files.peacecorps.gov/multimedia/audio/languagelessons/ghana/GH_Twi_Language_Lessons.pdf', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'accra', 'phrase', 'Maakye', 'Good morning. Use this Twi greeting before an early request at a hotel, cafe, shop, or market stall.', 'Pronunciation: mah-CHEH', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Good morning", "language": "Twi", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "mah-CHEH", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A respectful morning greeting before a request", "writer": "Automated Lore editorial research"}'::jsonb, 'https://files.peacecorps.gov/multimedia/audio/languagelessons/ghana/GH_Twi_Language_Lessons.pdf', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'accra', 'phrase', 'Mepa wo kyɛw', 'Please. Add it to a request and keep the greeting that opens the exchange; qualified Twi review remains pending.', 'Pronunciation: meh-pah woh chaw', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Please", "language": "Twi", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "meh-pah woh chaw", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A polite request marker", "writer": "Automated Lore editorial research"}'::jsonb, 'https://files.peacecorps.gov/multimedia/audio/languagelessons/ghana/GH_Twi_Language_Lessons.pdf', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'accra', 'phrase', 'Kafra', 'Excuse me or sorry. Use it gently when moving through a crowd or correcting a small misunderstanding.', 'Pronunciation: kah-FRAH', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Excuse me; sorry", "language": "Twi", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "kah-FRAH", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "For attention or a minor apology", "writer": "Automated Lore editorial research"}'::jsonb, 'https://files.peacecorps.gov/multimedia/audio/languagelessons/ghana/GH_Twi_Language_Lessons.pdf', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'accra', 'phrase', 'Mepɛ...', 'This means "I would like..." Point to the menu item only after saying the phrase, then confirm quantity and price.', 'Pronunciation: meh-PEH', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "I would like...", "language": "Twi", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "meh-PEH", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Ordering food, drink, or goods", "writer": "Automated Lore editorial research"}'::jsonb, 'https://files.peacecorps.gov/multimedia/audio/languagelessons/ghana/GH_Twi_Language_Lessons.pdf', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'accra', 'phrase', '...wɔ he?', 'Where is ...? Put the place first, then this question; show the written destination if pronunciation is unclear.', 'Pronunciation: ... woh HEH', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Where is ...?", "language": "Twi", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "... woh HEH", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Asking for a place or stop", "writer": "Automated Lore editorial research"}'::jsonb, 'https://files.peacecorps.gov/multimedia/audio/languagelessons/ghana/GH_Twi_Language_Lessons.pdf', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'accra', 'drink', 'Sobolo''s Ruby Spice', 'Sobolo is a deep-red, alcohol-free hibiscus drink often sharpened with ginger and warming spices. Recipes vary by household and maker, so notice whether yours leans tart, sweet, peppery, or fragrant rather than treating one version as definitive.', null, '🌺', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://gna.org.gh/2026/03/ghanas-ruby-elixir-celebrating-the-bold-spice-soul-of-sobolo/', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'accra', 'drink', 'Asaana''s Caramel Grain', 'Asaana is a nonalcoholic fermented-corn drink colored and sweetened with caramelized sugar. Buy from a clean, busy vendor and ask how today''s batch was stored.', null, '🌽', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.pulse.com.gh/story/how-to-make-asaana-caramelized-corn-drink-2024081010164416332', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'accra', 'etiquette', 'The Greeting Comes First', 'Offer a greeting before asking a question, browsing closely, or beginning a transaction. A calm hello and a little patience signal respect; avoid photographing people or their work without permission, especially in busy commercial spaces.', null, '🤝', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://files.peacecorps.gov/multimedia/audio/languagelessons/ghana/GH_Twi_Language_Lessons.pdf', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'accra', 'etiquette', 'Use the Right Hand for an Exchange', 'Offer money, food, or an object with the right hand, or support the right forearm with the left. If mobility makes that difficult, a warm explanation matters more than performance.', null, '🤲', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://files.peacecorps.gov/multimedia/audio/languagelessons/ghana/GH_Twi_Language_Lessons.pdf', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'accra', 'etiquette', 'Greet Around the Room', 'When a group is exchanging greetings, begin with the person on your right and continue around when handshakes are welcome. Follow local cues rather than forcing contact.', null, '🤝', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://files.peacecorps.gov/multimedia/audio/languagelessons/ghana/GH_Twi_Language_Lessons.pdf', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'accra', 'etiquette', 'Ask Before a Market Portrait', 'A colorful stall is still someone''s workplace. Buy or greet first, request permission for a close portrait, and accept a refusal without bargaining for access.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitghana.com/greater-accra/', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'accra', 'market', 'Makola, Read in Layers', 'Makola is less a single postcard scene than a working commercial district layered with food, cloth, household goods, movement, and conversation. Visit to observe how Accra trades and connects; keep walkways clear, ask before taking portraits, and let working shoppers set the pace.', null, '🧺', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitghana.com/greater-accra/', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'phrase', 'አመሰግናለሁ · Ameseginalehu', 'አመሰግናለሁ (ameseginalehu) means "thank you" in Amharic. Use it after someone gives directions, serves a drink, or helps with a purchase; a warm greeting before the request makes the exchange more natural.', 'Pronunciation: ameseginalehu', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Thank you", "language": "Amharic", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "ameseginalehu", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "ameseginalehu", "usage": "አመሰግናለሁ (ameseginalehu) means \"thank you\" in Amharic. Use it after someone gives directions, serves a drink, or helps with a purchase; a warm greeting before the request makes the exchange more natural.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Amharic_phrasebook', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'phrase', 'ሰላም · Selam', 'Hello. A simple greeting before a question or purchase makes the interaction feel less abrupt.', 'Pronunciation: seh-LAHM', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Hello", "language": "Amharic", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "seh-LAHM", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "An everyday greeting", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Amharic_phrasebook', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'phrase', 'እባክዎ · Ebakwo', 'Please. Use this polite form with an adult you do not know when asking for help, a menu item, or directions.', 'Pronunciation: eh-BAH-kwoh', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Please", "language": "Amharic", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "eh-BAH-kwoh", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A polite request to an unfamiliar adult", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Amharic_phrasebook', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'phrase', 'ይቅርታ · Yiqirta', 'Excuse me or sorry. Use it to get attention gently, pass in a crowded aisle, or repair a minor mistake.', 'Pronunciation: yih-KIR-tah', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Excuse me; sorry", "language": "Amharic", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "yih-KIR-tah", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Attention or a minor apology", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Amharic_phrasebook', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'phrase', '...አለ? · ...ale?', 'Do you have ...? Name or point to the item first, then ask; confirm ingredients separately if you have an allergy.', 'Pronunciation: ... ah-LEH', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Do you have ...?", "language": "Amharic", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "... ah-LEH", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Asking for a food, drink, or item", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Amharic_phrasebook', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'phrase', '...የት ነው? · ...yet new?', 'Where is ...? Show the destination name on your phone and use the phrase to confirm the direction.', 'Pronunciation: ... yeht NEH-oo', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Where is ...?", "language": "Amharic", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "... yeht NEH-oo", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Finding a place or transport stop", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Amharic_phrasebook', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'drink', 'Spris, a Layered Juice', 'Spris stacks fruit juices in bands, often using avocado, mango, papaya, or guava according to maker and season. This alcohol-free composition changes rather than following one recipe: admire the layers, then stir for a blended flavor.', null, '🥭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitethiopia.travel/downloads/AU_2025%20Brochure_English.pdf', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'drink', 'Buna, Not Just a Quick Coffee', 'Ethiopian coffee may arrive through a hosted ceremony rather than a rushed takeaway. Follow the host''s pace, notice aroma and conversation, and ask before declining another small cup.', null, '☕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitethiopia.travel/downloads/AU_2025%20Brochure_English.pdf', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'etiquette', 'Make Room for the Greeting', 'Greetings can be unhurried and relational, so do not launch immediately into a request. Follow your host''s lead around handshakes, shared food, and coffee; accept or decline gently, and never turn a ceremony or place of worship into a photo set without explicit permission.', null, '🫶', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/ethiopian-culture/ethiopian-culture-etiquette', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'etiquette', 'Coffee Follows the Host''s Pace', 'When invited to coffee, wait for the host''s cues before tasting or leaving. If caffeine or time is a concern, explain warmly rather than silently abandoning the cup.', null, '☕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/ethiopian-culture/ethiopian-culture-etiquette', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'etiquette', 'Right Hand, Shared Plate', 'Use the right hand when eating from a shared platter and take from the area nearest you. Ask before reaching across or separating food for dietary needs.', null, '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/ethiopian-culture/ethiopian-culture-etiquette', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'etiquette', 'Shoes and Cameras Wait at the Door', 'At a church or mosque, follow posted dress and shoe rules and ask before photographing worshippers, clergy, manuscripts, or an active service.', null, '🕯️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/ethiopian-culture/ethiopian-culture-etiquette', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'addis-ababa', 'market', 'Mercato Beyond the Superlative', 'Addis Mercato is often introduced through scale, but its organization into trades, goods, and relationships is more revealing. Go with a clear purpose or knowledgeable local guide, protect working space, and notice the craft and distribution networks behind what you see.', null, '🧵', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visitethiopia.travel/downloads/AU_2025%20Brochure_English.pdf', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'phrase', 'Niina marni', 'Niina marni (NEE-nah MAR-nee) is a Kaurna greeting meaning "hello, are you good?" Use it respectfully on Kaurna Country and learn its sounds from Kaurna-led resources; a shared greeting is not permission to borrow names, stories, or ceremony.', 'Pronunciation: NEE-nah MAR-nee', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Hello, are you good?", "language": "Kaurna", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "NEE-nah MAR-nee", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "NEE-nah MAR-nee", "usage": "Niina marni (NEE-nah MAR-nee) is a Kaurna greeting meaning \"hello, are you good?\" Use it respectfully on Kaurna Country and learn its sounds from Kaurna-led resources; a shared greeting is not permission to borrow names, stories, or ceremony.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.samuseum.sa.gov.au/getDocument/wkhfukn6z', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'phrase', 'Thanks, I appreciate it', 'Use this after directions, service, or help; stress appreciate rather than turning the whole sentence into a rush.', 'Pronunciation: thanks, eye uh-PREE-shee-ate it', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: thanks, eye uh-PREE-shee-ate it", "english": "Thanks, I appreciate it", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "thanks, eye uh-PREE-shee-ate it", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Warm everyday thanks", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/appreciate', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'phrase', 'Could you please...?', 'Use this for a polite request at a counter, hotel, or market stall; keep please light rather than overemphasized.', 'Pronunciation: could-yuh pleez', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: could-yuh pleez", "english": "Could you please...?", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "could-yuh pleez", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A polite request", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/please', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'phrase', 'Excuse me, could you help?', 'Use this before asking a stranger or staff member for help, then give one clear detail at a time.', 'Pronunciation: ex-KYOOZ mee, could-yuh help', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: ex-KYOOZ mee, could-yuh help", "english": "Excuse me, could you help?", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "ex-KYOOZ mee, could-yuh help", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Getting attention and asking for help", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/excuse-me', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'phrase', 'Could I have..., please?', 'Use this at a cafe or Central Market counter, naming the item and quantity before please.', 'Pronunciation: could-eye hav, pleez', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: could-eye hav, pleez", "english": "Could I have..., please?", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "could-eye hav, pleez", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Ordering food, drink, or goods", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/order', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'phrase', 'Which stop for...?', 'Use this before boarding a bus or tram and show the destination name to confirm the direction.', 'Pronunciation: which stop fuh', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: which stop fuh", "english": "Which stop for...?", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "which stop fuh", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Checking a public-transport stop", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.adelaidemetro.com.au/plan-a-trip/plan-my-journey', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'drink', 'A Long Black, Adelaide Pace', 'A long black is an alcohol-free espresso drink made by adding espresso to hot water, preserving more crema than an Americano. Adelaide''s cafe culture rewards slowing down: compare roast character and texture rather than ordering by size alone.', null, '☕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.australia.com/en-gb/places/adelaide-and-surrounds/best-coffee-shops.html', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'drink', 'Market Juice by the Season', 'At Adelaide Central Market, choose a zero-proof juice built around fruit that is in season. Ask what was pressed today and whether sugar or dairy was added.', null, '🧃', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://adelaidecentralmarket.com.au/', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'etiquette', 'Know Welcome From Acknowledgment', 'A Welcome to Country is given by traditional custodians; a visitor may offer an Acknowledgment. If using Kaurna language, follow Kaurna-led pronunciation resources and keep the wording tied to the place and occasion.', null, '🪶', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.samuseum.sa.gov.au/getDocument/wkhfukn6z', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'etiquette', 'Let the Tram Empty First', 'Stand clear of the doors, let riders exit, then board with a valid fare. Keep bags off seats when the tram is busy.', null, '🚋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.adelaidemetro.com.au/using-adelaide-metro', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'etiquette', 'Queue Without Crowding the Counter', 'Join the visible line, leave room for people collecting orders, and wait for an invitation before handling produce or craftwork.', null, '🧺', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/australian-culture/australian-culture-etiquette', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'etiquette', 'Country Is More Than an Acknowledgment', 'Adelaide is on Kaurna Country. Use shared names accurately and treat an acknowledgment as a living relationship rather than decorative wording.', null, '🪶', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://meetings.cityofadelaide.com.au/ieDecisionDetails.aspx?ID=2541', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'adelaide', 'market', 'Central Market by the Senses', 'Adelaide Central Market is best read through sound, aroma, produce, migration, and the people behind each counter. Browse without blocking regular shoppers, ask before photographing staff, and let seasonal ingredients tell you more than a fixed checklist ever could.', null, '🍑', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.australia.com/en-gb/places/adelaide-and-surrounds/best-cheap-eats.html', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'agra', 'phrase', '... कहाँ है? · ... kahā̃ hai?', '“... kahā̃ hai?” means “Where is ...?” Put the destination first and keep its written name ready.', 'Pronunciation: kuh-haan hai', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Where is ...?", "fact_review": "pending_human_fact_review", "intent": "navigation", "language": "Hindi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "... कहाँ है?", "pronunciation": "kuh-haan hai", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "... kahā̃ hai?", "source_publisher": "parivar.ciil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Put the destination first and keep its written name ready.", "usage_context": "Put the destination first and keep its written name ready.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://parivar.ciil.org/cexpressions.php?page=1', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'agra', 'phrase', 'क़ीमत क्या है · Qīmat kyā hai', 'This Hindi question means “What is the price?” Use it after pointing to one item, then confirm the amount before payment. Ask whether bargaining is expected; fixed-price craft emporia and market stalls operate differently.', 'Pronunciation: qīmat kyā hai', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "What is the price?", "fact_review": "pending_human_fact_review", "intent": "ordering", "language": "Hindi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "क़ीमत क्या है", "pronunciation": "qīmat kyā hai", "recheck_date": "2027-01-25", "register": "neutral-polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "qīmat kyā hai", "source_publisher": "parivar.ciil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Ask the price of one clearly indicated item.", "usage_context": "Useful in bazaars and shops; verify fixed versus negotiable pricing before bargaining.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://parivar.ciil.org/cexpressions.php?page=3', 'cc0', 121, 'reference_only'),
