(gen_random_uuid(), 'amsterdam', 'phrase', 'Dank u wel', 'A courteous Dutch thank-you for staff, hosts, or anyone you do not know. In relaxed conversation, the shorter dank je is common.', 'Pronunciation: dahnk oo vel', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Thank you", "fact_review": "pending_human_review", "language": "Dutch", "language_review": "pending_qualified_speaker_review", "original": "Dank u wel", "pronunciation": "dahnk oo vel", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Dutch phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "Use this polite form with staff, hosts, and strangers; use dank je informally.", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Dutch_phrasebook#Basics', 'cc0', 121, 'reference_only'),
