(gen_random_uuid(), 'amsterdam', 'phrase', 'Pardon, kunt u helpen?', '“Excuse me, can you help?” In Amsterdam, use this before asking a stranger or member of staff for help.', 'Pronunciation: par-DON, kunt oo HEL-pen', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Excuse me, can you help?", "fact_review": "pending_human_review", "language": "Dutch", "language_review": "pending_qualified_speaker_review", "original": "Pardon, kunt u helpen?", "pronunciation": "par-DON, kunt oo HEL-pen", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Dutch phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before asking a stranger or member of staff for help", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Dutch_phrasebook#Basics', 'cc0', 123, 'reference_only'),
