(gen_random_uuid(), 'athens', 'phrase', 'Θα ήθελα…', '“I would like…” In Athens, use this before an item when ordering food or tickets.', 'Pronunciation: tha EE-the-la', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "I would like…", "fact_review": "pending_human_review", "language": "Greek", "language_review": "pending_qualified_speaker_review", "original": "Θα ήθελα…", "pronunciation": "tha EE-the-la", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Greek phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before an item when ordering food or tickets", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Greek_phrasebook#Basics', 'cc0', 124, 'reference_only'),
