(gen_random_uuid(), 'bengaluru', 'phrase', 'ಕ್ಷಮಿಸಿ · kṣamisi', '“kṣamisi” means “Excuse me; sorry.” Use it to pass, apologize lightly, or get attention.', 'Pronunciation: kshuh-mee-see', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Excuse me; sorry", "fact_review": "pending_human_fact_review", "intent": "excuse", "language": "Kannada", "language_reviewer": "pending_qualified_speaker_review", "original_script": "ಕ್ಷಮಿಸಿ", "pronunciation": "kshuh-mee-see", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "kṣamisi", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it to pass, apologize lightly, or get attention.", "usage_context": "Use it to pass, apologize lightly, or get attention.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/kannada.php', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'bengaluru', 'phrase', 'ದಯವಿಟ್ಟು · dayaviṭṭu', '“dayaviṭṭu” means “Please.” Add it before a courteous request, then name the action or item you need.', 'Pronunciation: duh-yuh-vit-too', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Please", "fact_review": "pending_human_fact_review", "intent": "please", "language": "Kannada", "language_reviewer": "pending_qualified_speaker_review", "original_script": "ದಯವಿಟ್ಟು", "pronunciation": "duh-yuh-vit-too", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "dayaviṭṭu", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Add it before a courteous request.", "usage_context": "Add it before a courteous request.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/kannada.php', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'bengaluru', 'phrase', 'ಧನ್ಯವಾದಗಳು · Dhanyavādagaḷu', 'This respectful Kannada “thank you” is useful after directions, service, or hospitality. Bengaluru is deeply multilingual, and English, Hindi, Tamil, Telugu, Urdu, and other languages are also heard, so treat Kannada as an invitation, not a test.', 'Pronunciation: dhanyavādagaḷu', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Thank you", "fact_review": "pending_human_fact_review", "intent": "thanks", "language": "Kannada", "language_reviewer": "pending_qualified_speaker_review", "original_script": "ಧನ್ಯವಾದಗಳು", "pronunciation": "dhanyavādagaḷu", "recheck_date": "2027-01-25", "register": "respectful", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "dhanyavādagaḷu", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "A respectful expression of thanks after help, service, or hospitality.", "usage_context": "Appropriate in everyday interactions; Bengaluru is multilingual, so switch languages graciously if invited.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/kannada.php', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'bengaluru', 'phrase', 'ನಮಸ್ಕಾರ · namaskāra', '“namaskāra” means “Hello.” Offer it once on arrival, then let the other person’s language and register guide the exchange.', 'Pronunciation: nuh-muh-skaa-ruh', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Hello", "fact_review": "pending_human_fact_review", "intent": "greeting", "language": "Kannada", "language_reviewer": "pending_qualified_speaker_review", "original_script": "ನಮಸ್ಕಾರ", "pronunciation": "nuh-muh-skaa-ruh", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "namaskāra", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "A respectful everyday greeting.", "usage_context": "A respectful everyday greeting.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/kannada.php', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'bengaluru', 'drink', 'Filter kaapi, poured for aroma', 'Karnataka filter coffee combines a concentrated coffee decoction with hot milk, often aerated between a tumbler and bowl. It is nonalcoholic but caffeinated; sweetness and milk ratios vary, so ask for less sugar if preferred.', null, '☕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Usually contains dairy and caffeine; sugar level varies.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "South Indian coffee houses and homes", "source_publisher": "incredibleindia.gov.in", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/karnataka/bengaluru/the-delectable-cuisine-of-karnataka-13-must-try-local-dishes-in-bengaluru', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'bengaluru', 'drink', 'Majjige: a savory buttermilk reset', 'Majjige thins yogurt with water and may add salt, ginger, herbs, or chile. This nonalcoholic Karnataka drink is tangy rather than dessert-sweet; ingredients vary, so confirm dairy and spice.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Contains dairy; spice and salt vary.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Food and drink in Bengaluru", "source_publisher": "incredibleindia.gov.in", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/karnataka/bengaluru/the-delectable-cuisine-of-karnataka-13-must-try-local-dishes-in-bengaluru', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'bengaluru', 'etiquette', 'Ask before photographing at Gandhi Bazaar', 'Gandhi Bazaar''s flower, produce, and food sellers work at close quarters. Keep aisles open, frame displays without leaning over transactions, and ask before filming a vendor or customer.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "photography and shared-space courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "active worship spaces", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/karnataka/bengaluru/bengaluru-travel-and-food-guide', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'bengaluru', 'etiquette', 'Ask the counter''s rhythm at Gandhi Bazaar counters', 'Gandhi Bazaar''s flower, produce, and snack counters can move quickly. Wait until the seller acknowledges you, then confirm quantity, total, and payment method.', null, '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "ordering, queue, and payment courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Gandhi Bazaar counters", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/karnataka/bengaluru/bengaluru-travel-and-food-guide', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'bengaluru', 'etiquette', 'Make space on Namma Metro platforms', 'On Namma Metro, queue behind platform markings, let the train empty, and keep bags off seats and doorways. Station staff and signs take priority over informal habits.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "transit and queue courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Namma Metro platforms", "source_publisher": "english.bmrc.co.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://english.bmrc.co.in/', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'bengaluru', 'etiquette', 'Sacred spaces have their own house rules', 'Bengaluru’s temples, mosques, churches, and gurdwaras are active places of worship, not interchangeable attractions. Follow posted dress, shoe, photography, and entry guidance; keep voices low and give worshippers unhurried space.', null, '🕊️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "site-specific respectful conduct", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Active places of worship", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/faqs', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'bengaluru', 'market', 'Gandhi Bazaar: flowers, fruit, and daily life', 'Gandhi Bazaar is best read as a working neighborhood market: seasonal produce, flower garlands, spices, snacks, silk, and puja supplies move through the same streets. Keep pathways open and ask before photographing people at work.', null, '🌼', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "fact_review": "pending_human_fact_review", "mutable_details_excluded": true, "operation_recheck": "2027-01-25", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Neighborhood produce and flower market", "source_publisher": "incredibleindia.gov.in", "source_title": "Official destination market guide", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/karnataka/bengaluru/bengaluru-travel-and-food-guide', 'cc0', 150, 'reference_only'),
