(gen_random_uuid(), 'brisbane', 'phrase', 'No worries', '"No worries" is informal Australian English for "that''s okay," "you''re welcome," or "it isn''t a problem." Use it in relaxed exchanges after thanks or a minor inconvenience; in formal situations, plain "thank you" and "please" remain the safer choice.', 'Pronunciation: no WUR-eez', '👌', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "It''s okay; you''re welcome", "language": "Australian English", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "no WUR-eez", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "no WUR-eez", "usage": "\"No worries\" is informal Australian English for \"that''s okay,\" \"you''re welcome,\" or \"it isn''t a problem.\" Use it in relaxed exchanges after thanks or a minor inconvenience; in formal situations, plain \"thank you\" and \"please\" remain the safer choice.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.australia.com/en/facts-and-planning/about-australia/the-aussie-way-of-life.html', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'brisbane', 'phrase', 'G''day', 'Hello. Say it as one easy beat, guh-DAY, without stretching it into a performed accent.', 'Pronunciation: guh-DAY', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: guh-DAY", "english": "Hello", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "guh-DAY", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "An informal greeting", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/australian-culture/australian-culture-greetings', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'brisbane', 'phrase', 'Could you please...?', 'Use this for a polite request; keep the tone friendly and the request specific.', 'Pronunciation: could-yuh pleez', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: could-yuh pleez", "english": "Could you please...?", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "could-yuh pleez", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A polite request", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/please', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'brisbane', 'phrase', 'Excuse me, could you help?', 'Use this before asking a driver, station worker, or shop staff member for help.', 'Pronunciation: ex-KYOOZ mee, could-yuh help', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: ex-KYOOZ mee, could-yuh help", "english": "Excuse me, could you help?", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "ex-KYOOZ mee, could-yuh help", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Getting attention and asking for help", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/excuse-me', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'brisbane', 'phrase', 'Could I have..., please?', 'Use this when ordering, then specify size, ice, or dietary needs without relying on menu shorthand.', 'Pronunciation: could-eye hav, pleez', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: could-eye hav, pleez", "english": "Could I have..., please?", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "could-eye hav, pleez", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Ordering food or drink", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/order', 'cc0', 124, 'reference_only'),
