(gen_random_uuid(), 'frankfurt', 'market', 'Kleinmarkthalle', 'Frankfurt’s indoor market combines Hessian specialties with ingredients tied to the city’s international communities. Compare herb bundles for green sauce with the spices, breads, and produce around them.', 'Reference lead: Wikivoyage', '🌿', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Buy", "source_title": "Frankfurt travel guide: Buy", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Frankfurt#Buy', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'gold-coast', 'phrase', 'How are you going?', '"How are you going?" is Australian English for "how are you?" rather than a question about transport. Use it as a casual greeting; a short "good, thanks" is enough, and you can return the question without giving a travel itinerary.', 'Pronunciation: how are you GO-ing?', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "How are you?", "language": "Australian English", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "how are you GO-ing?", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "how are you GO-ing?", "usage": "\"How are you going?\" is Australian English for \"how are you?\" rather than a question about transport. Use it as a casual greeting; a short \"good, thanks\" is enough, and you can return the question without giving a travel itinerary.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/australian-culture/australian-culture-communication', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'gold-coast', 'phrase', 'Thanks, I appreciate it', 'Use this after directions, service, or help; keep the stress on appreciate and the tone relaxed.', 'Pronunciation: thanks, eye uh-PREE-shee-ate it', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: thanks, eye uh-PREE-shee-ate it", "english": "Thanks, I appreciate it", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "thanks, eye uh-PREE-shee-ate it", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Warm everyday thanks", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/appreciate', 'cc0', 121, 'reference_only'),
