(gen_random_uuid(), 'gold-coast', 'drink', 'Tropical Fruit, Beach-Cool', 'Choose an alcohol-free smoothie, cold-pressed juice, or sparkling water with local citrus after time in the sun. Ask what fruit is in season and whether syrups are added; hydration and a clear ingredient list matter more than a photogenic name.', null, '🍊', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.australia.com/en/places/gold-coast-and-surrounds/guide-to-the-gold-coast.html', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'gold-coast', 'drink', 'Iced Long Black, Beachside', 'Espresso, water, and ice make a crisp zero-proof coffee. Ask for decaf if needed and taste before adding syrup.', null, '🧊', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.australia.com/en/things-to-do/food-and-drinks/australian-coffee-cheat-sheet.html', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'gold-coast', 'etiquette', 'The Flags Are the Boundary', 'At patrolled beaches, swim between the red-and-yellow flags and follow lifeguard instructions even when the water looks calm. Keep dunes and wildlife undisturbed, take litter with you, and remember that beach safety guidance outranks the plan you arrived with.', null, '🚩', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.australia.com/en/facts-and-planning/useful-tips/beach-safety.html', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'gold-coast', 'etiquette', 'Swim Between the Flags', 'Enter patrolled water only between red-and-yellow flags, follow lifeguard directions, and never treat a closed beach as a challenge.', null, '🏊', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.australia.com/en/facts-and-planning/useful-tips/beach-safety.html', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'gold-coast', 'etiquette', 'Make Room on the G:link', 'Let G:link riders exit, move into the carriage, keep priority spaces free, and prepare the current fare method before boarding.', null, '🚈', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ridetheg.com.au/', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'gold-coast', 'etiquette', 'Wildlife Needs Food-Free Distance', 'Do not feed birds or wildlife for a photograph. Keep food secured, use bins, and follow ranger or venue instructions.', null, '🦜', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.qld.gov.au/environment/plants-animals/animals/living-with/feeding-wildlife', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'gold-coast', 'market', 'Carrara''s Local-Mix Maze', 'Carrara Markets mix produce, food, second-hand finds, craft, and family entertainment into a sprawling local institution. Skip the pressure to see everything: choose one theme, distinguish locally made work from imports, and ask before photographing traders or their displays.', null, '🛍️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://experiencegoldcoast.com/en/places-to-go/central-gold-coast/carrara', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'phrase', '... 喺邊度？ · ... hái bīndouh?', '“... hái bīndouh?” means “Where is ...?” Put the destination first or show its written name.', 'Pronunciation: high been-doh', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Where is ...?", "fact_review": "pending_human_fact_review", "intent": "navigation", "language": "Cantonese", "language_reviewer": "pending_qualified_speaker_review", "original_script": "... 喺邊度？", "pronunciation": "high been-doh", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "... hái bīndouh?", "source_publisher": "hkengage.gov.hk", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Put the destination first or show its written name.", "usage_context": "Put the destination first or show its written name.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.hkengage.gov.hk/zh-HK/essentials/living/useful-language-phrases', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'phrase', '你好 · néih hóu', '“néih hóu” means “Hello.” A simple greeting for shops and introductions.', 'Pronunciation: nay hoh', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Hello", "fact_review": "pending_human_fact_review", "intent": "greeting", "language": "Cantonese", "language_reviewer": "pending_qualified_speaker_review", "original_script": "你好", "pronunciation": "nay hoh", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "néih hóu", "source_publisher": "hkengage.gov.hk", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "A simple greeting for shops and introductions.", "usage_context": "A simple greeting for shops and introductions.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.hkengage.gov.hk/zh-HK/essentials/living/useful-language-phrases', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'phrase', '唔好意思 · m̀h hóu yi si', '“m̀h hóu yi si” means “Excuse me; sorry.” Use it to pass, apologize lightly, or get attention.', 'Pronunciation: mm-hoh yee-see', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Excuse me; sorry", "fact_review": "pending_human_fact_review", "intent": "excuse", "language": "Cantonese", "language_reviewer": "pending_qualified_speaker_review", "original_script": "唔好意思", "pronunciation": "mm-hoh yee-see", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "m̀h hóu yi si", "source_publisher": "hkengage.gov.hk", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it to pass, apologize lightly, or get attention.", "usage_context": "Use it to pass, apologize lightly, or get attention.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.hkengage.gov.hk/zh-HK/essentials/living/useful-language-phrases', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'phrase', '唔該 · M̀h''gōi', 'This compact Cantonese phrase can mean “please,” “excuse me,” or thanks for service and small favors. Guangzhou also uses Mandarin and many community languages, so listen for the language offered back and adapt without fuss.', 'Pronunciation: m̀h''gōi', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Please; excuse me; thank you for service", "fact_review": "pending_human_fact_review", "intent": "please", "language": "Cantonese", "language_reviewer": "pending_qualified_speaker_review", "original_script": "唔該", "pronunciation": "m̀h''gōi", "recheck_date": "2027-01-25", "register": "polite everyday", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "m̀h''gōi", "source_publisher": "hkengage.gov.hk", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Soften a request, get attention, or thank someone for service.", "usage_context": "Useful in Cantonese-speaking settings; Guangzhou is multilingual and Mandarin may be the shared language in many interactions.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.hkengage.gov.hk/zh-HK/essentials/living/useful-language-phrases', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'phrase', '多謝 · dōjeh', '“dōjeh” means “Thank you for a gift or favor.” Use it for something given or a personal favor.', 'Pronunciation: daw-jeh', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Thank you for a gift or favor", "fact_review": "pending_human_fact_review", "intent": "thanks", "language": "Cantonese", "language_reviewer": "pending_qualified_speaker_review", "original_script": "多謝", "pronunciation": "daw-jeh", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "dōjeh", "source_publisher": "hkengage.gov.hk", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it for something given or a personal favor.", "usage_context": "Use it for something given or a personal favor.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.hkengage.gov.hk/zh-HK/essentials/living/useful-language-phrases', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'phrase', '我要呢個 · ngóh yiu nī go', '“ngóh yiu nī go” means “I would like this.” Use it while indicating a menu item.', 'Pronunciation: ngaw yiu nee-gaw', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "I would like this", "fact_review": "pending_human_fact_review", "intent": "ordering", "language": "Cantonese", "language_reviewer": "pending_qualified_speaker_review", "original_script": "我要呢個", "pronunciation": "ngaw yiu nee-gaw", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "ngóh yiu nī go", "source_publisher": "hkengage.gov.hk", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it while indicating a menu item.", "usage_context": "Use it while indicating a menu item.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.hkengage.gov.hk/zh-HK/essentials/living/useful-language-phrases', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'drink', 'Chrysanthemum tea: a floral counterpoint', 'Chrysanthemum tea is a floral infusion connected with Guangzhou''s White Dew food customs. It is nonalcoholic; ask whether the cup is sweetened or blended with caffeinated tea because recipes vary.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Ask whether sugar or caffeinated tea is blended in.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Food and drink in Guangzhou", "source_publisher": "gz.gov.cn", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.gz.gov.cn/guangzhouinternational/home/citynews/content/post_9862271.html', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'drink', 'Liang cha: herbal tea by tradition', 'Guangdong herbal tea, or liang cha, is a family of nonalcoholic infusions rather than one recipe. Flavors range from lightly sweet to intensely bitter; ingredients vary, so ask before drinking if pregnant, medicated, or allergy-sensitive.', null, '🌿', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Botanical ingredients vary and may interact with medicines; ask for the ingredient list.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Herbal-tea shops and everyday Cantonese food culture", "source_publisher": "wglj.gz.gov.cn", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://wglj.gz.gov.cn/visitgz/ww/English/a/5009/684.html', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'etiquette', 'Keep Beijing Road workers out of surprise frames', 'Beijing Road mixes shops, archaeology, and heavy foot traffic. Frame displays from outside the transaction line, and ask workers or shoppers before recording them at close range.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "photography and shared-space courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "morning-tea dining rooms", "source_publisher": "gz.gov.cn", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.gz.gov.cn/ysgz/xwdt/ysdt/content/post_8617516.html', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'etiquette', 'Ask the counter''s rhythm at Beijing Road counters', 'On Beijing Road, the cashier and pickup counter may be separate. Identify the correct line, confirm the amount on screen, and move clear after payment.', null, '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "ordering, queue, and payment courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Beijing Road counters", "source_publisher": "gz.gov.cn", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.gz.gov.cn/ysgz/xwdt/ysdt/content/post_8617516.html', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'etiquette', 'Make space on Guangzhou Metro platforms', 'Guangzhou Metro entry includes screening. Follow platform arrows, let riders exit, and move inward after boarding rather than stopping at the door.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "transit and queue courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Guangzhou Metro platforms", "source_publisher": "gz.gov.cn", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.gz.gov.cn/guangzhouinternational/home/citynews/content/post_9596286.html', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'etiquette', 'Morning tea is culture, not a checklist', 'Guangzhou’s official visitor guide describes morning tea, snacks, and dim sum as integral to Guangdong food culture. Approach the table as a guest: confirm unfamiliar ingredients, follow your host or server’s cues, and avoid presenting one household’s habits as universal rules.', null, '🫖', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "context-led dining courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Guangzhou morning tea and dim sum", "source_publisher": "gz.gov.cn", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.gz.gov.cn/guangzhouinternational/visitors/whattodine/snacks/', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'guangzhou', 'market', 'Beijing Road: commerce above archaeology', 'Beijing Road layers a modern pedestrian shopping district over preserved traces of earlier city streets. Look through the archaeological displays without blocking foot traffic, compare craft claims carefully, and treat nearby temples as active sacred places.', null, '🛍️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "fact_review": "pending_human_fact_review", "mutable_details_excluded": true, "operation_recheck": "2027-01-25", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Historic pedestrian commercial street", "source_publisher": "gz.gov.cn", "source_title": "Official destination market guide", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.gz.gov.cn/ysgz/xwdt/ysdt/content/post_8617516.html', 'cc0', 150, 'reference_only'),
