(gen_random_uuid(), 'hyderabad', 'phrase', 'క్షమించండి · kṣamin̄caṇḍi', '“kṣamin̄caṇḍi” means “Excuse me; sorry.” Use it to apologize lightly or get attention.', 'Pronunciation: kshuh-min-chun-dee', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Excuse me; sorry", "fact_review": "pending_human_fact_review", "intent": "excuse", "language": "Telugu", "language_reviewer": "pending_qualified_speaker_review", "original_script": "క్షమించండి", "pronunciation": "kshuh-min-chun-dee", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "kṣamin̄caṇḍi", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it to apologize lightly or get attention.", "usage_context": "Use it to apologize lightly or get attention.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/telugu.php', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'hyderabad', 'phrase', 'దయచేసి · dayacēsi', '“dayacēsi” means “Please.” Add it to a courteous request, then make the needed action or item explicit.', 'Pronunciation: duh-yuh-chay-see', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Please", "fact_review": "pending_human_fact_review", "intent": "please", "language": "Telugu", "language_reviewer": "pending_qualified_speaker_review", "original_script": "దయచేసి", "pronunciation": "duh-yuh-chay-see", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "dayacēsi", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Add it to a courteous request.", "usage_context": "Add it to a courteous request.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/telugu.php', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'hyderabad', 'phrase', 'ధన్యవాదాలు · Dhanyavādālu', '“Dhanyavādālu” is a respectful Telugu “thank you.” Hyderabad is multilingual, with Telugu, Dakhni Urdu, Hindi, English, and many other languages in daily use, so offer it kindly and adapt to the reply.', 'Pronunciation: dhanyavādālu', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Thank you.", "fact_review": "pending_human_fact_review", "intent": "thanks", "language": "Telugu", "language_reviewer": "pending_qualified_speaker_review", "original_script": "ధన్యవాదాలు", "pronunciation": "dhanyavādālu", "recheck_date": "2027-01-25", "register": "respectful", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "dhanyavādālu", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Express respectful thanks after help, hospitality, directions, or service.", "usage_context": "Appropriate in everyday interactions; Hyderabad is multilingual, so follow the other person’s language lead.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/telugu.php', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'hyderabad', 'phrase', 'నమస్కారం · namaskāraṁ', '“namaskāraṁ” means “Hello.” Use it once when arriving, then follow the other person’s language and degree of formality.', 'Pronunciation: nuh-muh-skaa-rum', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Hello", "fact_review": "pending_human_fact_review", "intent": "greeting", "language": "Telugu", "language_reviewer": "pending_qualified_speaker_review", "original_script": "నమస్కారం", "pronunciation": "nuh-muh-skaa-rum", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "namaskāraṁ", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "A respectful everyday greeting.", "usage_context": "A respectful everyday greeting.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/telugu.php', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'hyderabad', 'drink', 'Badam milk: nuts, milk, and spice', 'Badam milk blends dairy with almonds, sugar, and warming spices, served chilled or hot around Hyderabad. It is nonalcoholic; confirm nuts, dairy, and sweetness before ordering.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Contains dairy and tree nuts in traditional recipes.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Food and drink in Hyderabad", "source_publisher": "incredibleindia.gov.in", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/telangana/hyderabad/the-best-local-foods-in-hyderabad', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'hyderabad', 'drink', 'Irani chai: two brews meet in one cup', 'Hyderabadi Irani chai combines separately brewed strong tea and rich milk, often paired with an Osmania biscuit. It is nonalcoholic but caffeinated, dairy-heavy, and sweet; ask for adjustments rather than assuming one recipe.', null, '🫖', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Usually contains dairy, sugar, and caffeine.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Hyderabadi café culture", "source_publisher": "incredibleindia.gov.in", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/telangana/hyderabad/the-best-local-foods-in-hyderabad', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'hyderabad', 'etiquette', 'Ask before filming work at Laad Bazaar', 'Laad Bazaar''s bangle shops place skilled work close to the lane. Photograph displays without leaning into a transaction, and ask before filming artisans, sellers, or shoppers.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "photography and shared-space courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "active faith sites in the old city", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/telangana/hyderabad/the-best-places-to-shop-in-hyderabad-for-every-budget', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'hyderabad', 'etiquette', 'Ask the counter''s rhythm at Laad Bazaar counters', 'At Laad Bazaar, bangle size, material, and set count affect the price. Confirm all three and the final total before the seller wraps the purchase.', null, '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "ordering, queue, and payment courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Laad Bazaar counters", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/telangana/hyderabad/the-best-places-to-shop-in-hyderabad-for-every-budget', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'hyderabad', 'etiquette', 'Make space on Hyderabad Metro platforms', 'At Hyderabad Metro stations, complete screening without blocking the entrance, queue behind platform markings, and keep priority seating and doors available.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "transit and queue courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Hyderabad Metro platforms", "source_publisher": "ltmetro.com", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ltmetro.com/', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'hyderabad', 'etiquette', 'The old city holds many devotions', 'Around Charminar, mosques, temples, and processional routes share dense streets with commerce. Keep entrances open, dress for the specific site, ask before photography, and let prayer, festival, or community movement outrank sightseeing convenience.', null, '🕊️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "site-specific respectful conduct", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Active places of worship and old-city streets", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/faqs', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'hyderabad', 'market', 'Laad Bazaar: bangles with a material story', 'Laad Bazaar is associated with lacquer bangles, wedding accessories, textiles, perfumes, and old-city shopping. Ask about base material, embellishment, sizing, and care, and request permission before filming artisans or customers trying on jewelry.', null, '✨', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "fact_review": "pending_human_fact_review", "mutable_details_excluded": true, "operation_recheck": "2027-01-25", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Historic bangle and wedding-goods market", "source_publisher": "incredibleindia.gov.in", "source_title": "Official destination market guide", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/telangana/hyderabad/the-best-places-to-shop-in-hyderabad-for-every-budget', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'phrase', '... nerede? · ... nerede?', '“... nerede?” means “Where is ...?” Put the destination first or show its written name.', 'Pronunciation: neh-reh-deh', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Where is ...?", "fact_review": "pending_human_fact_review", "intent": "navigation", "language": "Turkish", "language_reviewer": "pending_qualified_speaker_review", "original_script": "... nerede?", "pronunciation": "neh-reh-deh", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "... nerede?", "source_publisher": "turkishcouncil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Put the destination first or show its written name.", "usage_context": "Put the destination first or show its written name.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.turkishcouncil.org/turkish-for-travelers-essential-phrases-for-your-next-trip/', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'phrase', 'Affedersiniz', '“Affedersiniz” is a courteous Turkish “excuse me” or “pardon me.” Use it before asking directions, addressing a stranger, or moving past someone. A softer “pardon” is also common, but register changes with context.', 'Pronunciation: affedersiniz', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Excuse me; pardon me", "fact_review": "pending_human_fact_review", "intent": "excuse", "language": "Turkish", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Affedersiniz", "pronunciation": "affedersiniz", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "affedersiniz", "source_publisher": "turkishcouncil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Politely get attention, preface a question, or apologize for a small interruption.", "usage_context": "Useful with strangers and service staff; pair with a specific request rather than repeating loudly.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.turkishcouncil.org/turkish-for-travelers-essential-phrases-for-your-next-trip/', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'phrase', 'Bunu alabilir miyim? · bunu alabilir miyim?', '“bunu alabilir miyim?” means “May I have this?” Use it while indicating a menu item.', 'Pronunciation: boo-noo ah-lah-bee-leer mee-yeem', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "May I have this?", "fact_review": "pending_human_fact_review", "intent": "ordering", "language": "Turkish", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Bunu alabilir miyim?", "pronunciation": "boo-noo ah-lah-bee-leer mee-yeem", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "bunu alabilir miyim?", "source_publisher": "turkishcouncil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it while indicating a menu item.", "usage_context": "Use it while indicating a menu item.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.turkishcouncil.org/turkish-for-travelers-essential-phrases-for-your-next-trip/', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'phrase', 'Lütfen · lütfen', '“lütfen” means “Please.” Add it to a courteous request instead of using the word as a complete demand.', 'Pronunciation: loot-fehn', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Please", "fact_review": "pending_human_fact_review", "intent": "please", "language": "Turkish", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Lütfen", "pronunciation": "loot-fehn", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "lütfen", "source_publisher": "turkishcouncil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Add it to a courteous request.", "usage_context": "Add it to a courteous request.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.turkishcouncil.org/turkish-for-travelers-essential-phrases-for-your-next-trip/', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'phrase', 'Merhaba · merhaba', '“merhaba” means “Hello.” Use it at the start of an exchange, then let the response set a formal or casual tone.', 'Pronunciation: mehr-hah-bah', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Hello", "fact_review": "pending_human_fact_review", "intent": "greeting", "language": "Turkish", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Merhaba", "pronunciation": "mehr-hah-bah", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "merhaba", "source_publisher": "turkishcouncil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "A simple everyday greeting.", "usage_context": "A simple everyday greeting.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.turkishcouncil.org/turkish-for-travelers-essential-phrases-for-your-next-trip/', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'phrase', 'Teşekkür ederim · teşekkür ederim', '“teşekkür ederim” means “Thank you.” Use it after help, service, or directions.', 'Pronunciation: teh-shehk-kur eh-deh-reem', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Thank you", "fact_review": "pending_human_fact_review", "intent": "thanks", "language": "Turkish", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Teşekkür ederim", "pronunciation": "teh-shehk-kur eh-deh-reem", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "teşekkür ederim", "source_publisher": "turkishcouncil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it after help, service, or directions.", "usage_context": "Use it after help, service, or directions.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.turkishcouncil.org/turkish-for-travelers-essential-phrases-for-your-next-trip/', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'drink', 'Salep: Istanbul’s winter cup', 'Salep is a thick, nonalcoholic hot drink made with milk, sugar, and powdered orchid tuber, usually finished with cinnamon. It is especially associated with winter; ask about dairy and sourcing if allergies or conservation concerns matter.', null, '🥛', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Usually contains dairy; wild orchid harvesting has conservation implications, so responsible sourcing matters.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Cold-weather cafés and street culture", "source_publisher": "goturkiye.com", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://goturkiye.com/branding/press-releases/the-unique-turkish-flavours-that-warm-up-istanbul-winters-salep-and-boza', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'drink', 'Türk kahvesi: coffee with a long finish', 'Turkish coffee is brewed finely ground and served unfiltered in a small cup; let the grounds settle rather than drinking to the bottom. It is nonalcoholic and caffeinated, and sweetness is usually chosen before brewing.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Caffeinated; sugar choice is made before brewing.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Food and drink in Istanbul", "source_publisher": "ich.unesco.org", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ich.unesco.org/en/RL/turkish-coffee-culture-and-tradition-00645', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'etiquette', 'A mosque is worship first, landmark second', 'Enter only through the visitor route, dress modestly, remove shoes where required, silence devices, and never step in front of someone praying. Access can pause for worship, so posted guidance always outranks a sightseeing plan.', null, '🕌', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "sacred-site conduct", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Active mosques", "source_publisher": "visitistanbul.com", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.visitistanbul.com/plan-your-trip/essential-istanbul-travel-tips-cultural-etiquette-safety-local-customs/', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'etiquette', 'Arasta Bazaar sits beside active worship', 'Arasta Bazaar borders the Blue Mosque complex. Keep worship routes and shop entrances clear, follow posted camera rules, and ask before photographing merchants, craftspeople, or visitors.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "photography and shared-space courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "active mosque courtyards", "source_publisher": "goturkiye.com", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://goturkiye.com/istanbul/arasta-bazaar', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'etiquette', 'Ask the counter''s rhythm at Arasta Bazaar stalls', 'At Arasta Bazaar, ask whether a price is fixed, then discuss material, maker, and total without treating bargaining as theater. Obtain paperwork for valuable goods.', null, '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "ordering, queue, and payment courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Arasta Bazaar stalls", "source_publisher": "goturkiye.com", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://goturkiye.com/istanbul/arasta-bazaar', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'etiquette', 'Make space on Istanbul trams, metros, and ferries', 'Istanbul''s trams, metros, ferries, and buses use different boarding layouts. Confirm direction first, let riders exit, and keep ferry landings and vehicle doors clear.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "transit and queue courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Istanbul trams, metros, and ferries", "source_publisher": "iett.istanbul", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://iett.istanbul/', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'istanbul', 'market', 'Arasta Bazaar: craft lanes beside worship', 'Arasta Bazaar’s compact lanes near the Blue Mosque foreground textiles, ceramics, and traditional craft retail. Keep mosque approaches clear, compare workmanship instead of chasing a “lowest” price, and ask before photographing a maker or their close-up process.', null, '🧿', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "fact_review": "pending_human_fact_review", "mutable_details_excluded": true, "operation_recheck": "2027-01-25", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Historic covered-market lanes", "source_publisher": "goturkiye.com", "source_title": "Official destination market guide", "writer": "Automated Lore editorial research"}'::jsonb, 'https://goturkiye.com/istanbul/arasta-bazaar', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'phrase', '... कहाँ है? · ... kahā̃ hai?', '“... kahā̃ hai?” means “Where is ...?” Put the destination first and keep its written name ready.', 'Pronunciation: kuh-haan hai', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Where is ...?", "fact_review": "pending_human_fact_review", "intent": "navigation", "language": "Hindi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "... कहाँ है?", "pronunciation": "kuh-haan hai", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "... kahā̃ hai?", "source_publisher": "parivar.ciil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Put the destination first and keep its written name ready.", "usage_context": "Put the destination first and keep its written name ready.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://parivar.ciil.org/cexpressions.php?page=1', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'phrase', 'कृपया · Kṛpayā', '“Kṛpayā” means “please” in formal Hindi and can politely introduce a request. Jaipur also speaks Rajasthani varieties, including Dhundhari, alongside Hindi, English, Urdu, and other languages; listen for the language offered back.', 'Pronunciation: kṛpayā', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Please.", "fact_review": "pending_human_fact_review", "intent": "please", "language": "Hindi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "कृपया", "pronunciation": "kṛpayā", "recheck_date": "2027-01-25", "register": "formal-polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "kṛpayā", "source_publisher": "parivar.ciil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Add politeness to a request, especially in formal or written contexts.", "usage_context": "Useful but somewhat formal in speech; Jaipur is multilingual, so follow the other person’s language and register.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://parivar.ciil.org/cexpressions.php?page=1', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'phrase', 'धन्यवाद · dhanyavād', '“dhanyavād” means “Thank you.” Use it after help, service, or directions.', 'Pronunciation: dhun-yuh-vaad', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Thank you", "fact_review": "pending_human_fact_review", "intent": "thanks", "language": "Hindi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "धन्यवाद", "pronunciation": "dhun-yuh-vaad", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "dhanyavād", "source_publisher": "parivar.ciil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it after help, service, or directions.", "usage_context": "Use it after help, service, or directions.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://parivar.ciil.org/cexpressions.php?page=1', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'phrase', 'नमस्ते · namaste', '“namaste” means “Hello.” A respectful all-purpose greeting for arrival or departure.', 'Pronunciation: nuh-muh-stay', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Hello", "fact_review": "pending_human_fact_review", "intent": "greeting", "language": "Hindi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "नमस्ते", "pronunciation": "nuh-muh-stay", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "namaste", "source_publisher": "parivar.ciil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "A respectful all-purpose greeting for arrival or departure.", "usage_context": "A respectful all-purpose greeting for arrival or departure.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://parivar.ciil.org/cexpressions.php?page=1', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'phrase', 'माफ़ कीजिए · māf kījie', '“māf kījie” means “Excuse me; sorry.” Use it to apologize lightly, pass through, or get attention.', 'Pronunciation: maaf kee-jee-yay', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Excuse me; sorry", "fact_review": "pending_human_fact_review", "intent": "excuse", "language": "Hindi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "माफ़ कीजिए", "pronunciation": "maaf kee-jee-yay", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "māf kījie", "source_publisher": "parivar.ciil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it to apologize lightly, pass through, or get attention.", "usage_context": "Use it to apologize lightly, pass through, or get attention.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://parivar.ciil.org/cexpressions.php?page=1', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'phrase', 'मुझे यह चाहिए · mujhe yah chāhie', '“mujhe yah chāhie” means “I would like this.” Pair it with a menu item or a clear point at the counter.', 'Pronunciation: moo-jhay yuh chaa-hee-yay', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "I would like this", "fact_review": "pending_human_fact_review", "intent": "ordering", "language": "Hindi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "मुझे यह चाहिए", "pronunciation": "moo-jhay yuh chaa-hee-yay", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "mujhe yah chāhie", "source_publisher": "parivar.ciil.org", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Pair it with a menu item or a clear point at the counter.", "usage_context": "Pair it with a menu item or a clear point at the counter.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://parivar.ciil.org/cexpressions.php?page=1', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'drink', 'Chaas: savory buttermilk for the table', 'Chaas is yogurt thinned with water and seasoned, often with cumin, salt, or herbs. This nonalcoholic Rajasthan drink is light and savory; recipes vary, so confirm dairy and chile.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Contains dairy; salt and spice vary.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Food and drink in Jaipur", "source_publisher": "incredibleindia.gov.in", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/trips/trip-listing/journey-through-jaipurs-timeless-treasures', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'drink', 'Lassi: yogurt against the desert heat', 'Jaipur lassi is a chilled yogurt drink served sweet, salted, or flavored, often with a thick texture. It is nonalcoholic; confirm dairy, sugar, ice, and toppings, especially when heat makes hydration more important than novelty.', null, '🥛', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Contains dairy; sugar, ice, fruit, and toppings vary.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Street-food and casual dining culture", "source_publisher": "incredibleindia.gov.in", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/trips/trip-listing/journey-through-jaipurs-timeless-treasures', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'etiquette', 'Johari Bazaar craft is not blanket consent', 'Johari Bazaar''s jewelry and textile work is visible from public lanes, but people are not display objects. Ask artisans, staff, and shoppers before close photographs and honor every no-photo sign.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "photography and shared-space courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "palace and temple thresholds", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/rajasthan/jaipur', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'etiquette', 'Ask the counter''s rhythm at Johari Bazaar counters', 'At Johari Bazaar, ask for material details and independent documentation rather than relying on a verbal provenance story. Agree on the complete total before payment.', null, '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "ordering, queue, and payment courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Johari Bazaar counters", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/rajasthan/jaipur', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'etiquette', 'Make space on Jaipur Metro and old-city approaches', 'Jaipur Metro stations and old-city approaches have different crowd flows. Follow barriers and staff, and stop for directions away from gates and crossings.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "transit and queue courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Jaipur Metro and old-city approaches", "source_publisher": "transport.rajasthan.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://transport.rajasthan.gov.in/jmrc', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'etiquette', 'Palace, temple, and market are different rooms', 'Jaipur’s forts, palaces, temples, and bazaars overlap geographically but not behaviorally. Follow each site’s shoe, dress, photography, and restricted-area rules; in active worship spaces, quiet access and devotee movement take priority.', null, '🕊️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "site-specific respectful conduct", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Heritage monuments and active places of worship", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/faqs', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'jaipur', 'market', 'Johari Bazaar: ask how the work was made', 'Johari Bazaar and nearby old-city markets are known for jewelry, textiles, block prints, bangles, carpets, and footwear. Ask about metal purity, stone treatment, material, and maker; ornate presentation is not the same as certification.', null, '💎', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "fact_review": "pending_human_fact_review", "mutable_details_excluded": true, "operation_recheck": "2027-01-25", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Historic jewelry and textile market district", "source_publisher": "incredibleindia.gov.in", "source_title": "Official destination market guide", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/rajasthan/jaipur', 'cc0', 150, 'reference_only'),
