(gen_random_uuid(), 'krakow', 'phrase', 'Przepraszam, czy może mi pan/pani pomóc?', '“Excuse me, can you help me?” In Kraków, use this before asking an adult for help.', 'Pronunciation: psheh-PRAH-shahm, chih MOH-zhe mee pahn/PAH-nee POH-moots', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Excuse me, can you help me?", "fact_review": "pending_human_review", "language": "Polish", "language_review": "pending_qualified_speaker_review", "original": "Przepraszam, czy może mi pan/pani pomóc?", "pronunciation": "psheh-PRAH-shahm, chih MOH-zhe mee pahn/PAH-nee POH-moots", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Polish phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before asking an adult for help", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Polish_phrasebook#Basics', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'krakow', 'phrase', 'Poproszę…', '“I would like…” In Kraków, use this before a menu item, quantity, or ticket.', 'Pronunciation: poh-PROH-sheh', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "I would like…", "fact_review": "pending_human_review", "language": "Polish", "language_review": "pending_qualified_speaker_review", "original": "Poproszę…", "pronunciation": "poh-PROH-sheh", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Polish phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before a menu item, quantity, or ticket", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Polish_phrasebook#Basics', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'krakow', 'phrase', 'Gdzie jest…?', '“Where is…?” In Kraków, use this before a station, street, toilet, or landmark.', 'Pronunciation: gjeh yest', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Where is…?", "fact_review": "pending_human_review", "language": "Polish", "language_review": "pending_qualified_speaker_review", "original": "Gdzie jest…?", "pronunciation": "gjeh yest", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Polish phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before a station, street, toilet, or landmark", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Polish_phrasebook#Basics', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'krakow', 'drink', 'Kompot', 'Kompot is fruit simmered in water with sugar, then served as a home-style soft drink. Ingredients shift with the season and may include apples, berries, plums, or rhubarb.', 'Reference lead: Wikivoyage', '🍒', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "nonalcoholic": true, "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Eat", "source_title": "Kraków travel guide: Eat", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Krakow#Eat', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'krakow', 'drink', 'Herbata z cytryną', 'Black tea with lemon is a simple, nonalcoholic but caffeinated café order; honey or sugar may arrive separately, so sweeten to taste.', 'Reference lead: Wikivoyage', '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "nonalcoholic": true, "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Eat", "source_title": "Kraków travel guide: Eat", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Krakow#Eat', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'krakow', 'etiquette', 'Jewish heritage is living history', 'Kazimierz is not a theatrical backdrop. Visit synagogues and memorial sites with care, distinguish active institutions from entertainment venues, and avoid staged “old Jewish quarter” stereotypes.', 'Reference lead: Wikivoyage', '🕯️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Respect", "source_title": "Kraków travel guide: Respect", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Krakow#Respect', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'krakow', 'etiquette', 'Share trams, buses, and dense Old Town pedestrian routes', 'On trams, buses, and dense Old Town pedestrian routes in Kraków, let riders leave first, keep doors and aisles clear, and follow posted ticket or validation instructions; fare rules can change.', 'Reference lead: Wikivoyage', '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Get around", "source_title": "Kraków travel guide: Get around", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Krakow#Get_around', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'krakow', 'etiquette', 'Browse Stary Kleparz with care', 'At Stary Kleparz, keep aisles open, ask before handling produce or photographing traders, and follow stall signs. Browsing should not interrupt Kraków''s everyday shopping.', 'Reference lead: Wikivoyage', '🧺', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Buy", "source_title": "Kraków travel guide: Buy", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Krakow#Buy', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'krakow', 'etiquette', 'Enter Wawel Cathedral as a guest', 'At Wawel Cathedral, follow posted rules, silence devices, and ask before photographing people or services. Its role as an active Catholic cathedral and national shrine comes before a visitor''s photograph.', 'Reference lead: Wikivoyage', '🕯️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "See", "source_title": "Kraków travel guide: See", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Krakow#See', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'krakow', 'market', 'Stary Kleparz', 'Kraków’s old Kleparz market remains a practical source for produce, flowers, cheese, bread, and pantry goods. Its everyday pace offers a counterpoint to the monumental Main Square.', 'Reference lead: Wikivoyage', '🥕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Buy", "source_title": "Kraków travel guide: Buy", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Krakow#Buy', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'phrase', 'Di mana ...? · di mana ...?', '“di mana ...?” means “Where is ...?” Put the destination after di mana or show its written name.', 'Pronunciation: dee mah-nah', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Where is ...?", "fact_review": "pending_human_fact_review", "intent": "navigation", "language": "Malay", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Di mana ...?", "pronunciation": "dee mah-nah", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "di mana ...?", "source_publisher": "ebrochures.malaysia.travel", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Put the destination after di mana or show its written name.", "usage_context": "Put the destination after di mana or show its written name.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ebrochures.malaysia.travel/en/kuala-lumpur/56-67-useful-information/', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'phrase', 'Maaf · maaf', '“maaf” means “Excuse me; sorry.” Use it to pass, apologize lightly, or get attention.', 'Pronunciation: mah-ahf', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Excuse me; sorry", "fact_review": "pending_human_fact_review", "intent": "excuse", "language": "Malay", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Maaf", "pronunciation": "mah-ahf", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "maaf", "source_publisher": "ebrochures.malaysia.travel", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it to pass, apologize lightly, or get attention.", "usage_context": "Use it to pass, apologize lightly, or get attention.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ebrochures.malaysia.travel/en/kuala-lumpur/56-67-useful-information/', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'phrase', 'Saya mahu ini · saya mahu ini', '“saya mahu ini” means “I would like this.” Use it while indicating a menu item.', 'Pronunciation: sah-yah mah-hoo ee-nee', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "I would like this", "fact_review": "pending_human_fact_review", "intent": "ordering", "language": "Malay", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Saya mahu ini", "pronunciation": "sah-yah mah-hoo ee-nee", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "saya mahu ini", "source_publisher": "ebrochures.malaysia.travel", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it while indicating a menu item.", "usage_context": "Use it while indicating a menu item.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ebrochures.malaysia.travel/en/kuala-lumpur/56-67-useful-information/', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'phrase', 'Selamat sejahtera · selamat sejahtera', '“selamat sejahtera” means “Greetings.” A polite neutral greeting in multilingual settings.', 'Pronunciation: suh-lah-mat suh-jah-truh', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Greetings", "fact_review": "pending_human_fact_review", "intent": "greeting", "language": "Malay", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Selamat sejahtera", "pronunciation": "suh-lah-mat suh-jah-truh", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "selamat sejahtera", "source_publisher": "ebrochures.malaysia.travel", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "A polite neutral greeting in multilingual settings.", "usage_context": "A polite neutral greeting in multilingual settings.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ebrochures.malaysia.travel/en/kuala-lumpur/56-67-useful-information/', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'phrase', 'Terima kasih', '“Terima kasih” is Malay for “thank you.” Kuala Lumpur is multilingual, with Malay, English, Mandarin varieties, Tamil, and many community languages in use, so offer the phrase naturally and follow the language chosen in response.', 'Pronunciation: terima kasih', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Thank you.", "fact_review": "pending_human_fact_review", "intent": "thanks", "language": "Malay", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Terima kasih", "pronunciation": "terima kasih", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "terima kasih", "source_publisher": "ebrochures.malaysia.travel", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Express thanks after help, hospitality, directions, or service.", "usage_context": "A courteous Malay phrase in multilingual Kuala Lumpur; English may be the practical shared language in many visitor settings.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ebrochures.malaysia.travel/en/kuala-lumpur/56-67-useful-information/', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'phrase', 'Tolong · tolong', '“tolong” means “Please; help.” Use it before a request, especially when asking for assistance.', 'Pronunciation: toh-long', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Please; help", "fact_review": "pending_human_fact_review", "intent": "please", "language": "Malay", "language_reviewer": "pending_qualified_speaker_review", "original_script": "Tolong", "pronunciation": "toh-long", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "tolong", "source_publisher": "ebrochures.malaysia.travel", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it before a request, especially when asking for assistance.", "usage_context": "Use it before a request, especially when asking for assistance.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ebrochures.malaysia.travel/en/kuala-lumpur/56-67-useful-information/', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'drink', 'Air bandung: rose-pink and chilled', 'Air bandung combines milk with rose-flavored syrup for a sweet, cold drink found at Malaysian food counters. It is nonalcoholic; confirm dairy, ice, and sweetness when ordering.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Usually dairy and highly sweetened.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Food and drink in Kuala Lumpur", "source_publisher": "ebrochures.malaysia.travel", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ebrochures.malaysia.travel/en/kuala-lumpur/45-49-eating-out/', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'drink', 'Teh tarik: tea pulled into foam', 'Teh tarik is black tea mixed with evaporated or condensed milk and poured between vessels to cool and aerate it. It is nonalcoholic but caffeinated and sweet; “kurang manis” asks for less sweetness.', null, '🫖', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Usually contains dairy, sugar, and caffeine.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Mamak stalls, food courts, and cafés", "source_publisher": "ebrochures.malaysia.travel", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ebrochures.malaysia.travel/en/kuala-lumpur/45-49-eating-out/', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'etiquette', 'Central Market vendors choose their own visibility', 'Central Market''s craft and food stalls are active workplaces. Keep entrances and demonstrations clear, and ask vendors or customers before making a close portrait or video.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "photography and shared-space courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "active mosque grounds", "source_publisher": "malaysia.travel", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.malaysia.travel/explore/central-market-kuala-lumpur', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'etiquette', 'Ask the counter''s rhythm at Central Market stalls', 'Fixed-price shops and negotiable stalls coexist at Central Market. Ask which applies, verify materials, and confirm the complete total before tapping or handing over cash.', null, '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "ordering, queue, and payment courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Central Market stalls", "source_publisher": "malaysia.travel", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.malaysia.travel/explore/central-market-kuala-lumpur', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'etiquette', 'Make space on Kuala Lumpur LRT and MRT platforms', 'On Kuala Lumpur rail, check the line, direction, and platform before the gate. Queue at markings, allow riders off, and leave priority areas usable.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "transit and queue courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Kuala Lumpur LRT and MRT platforms", "source_publisher": "myrapid.com.my", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://myrapid.com.my/', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'etiquette', 'Masjid Jamek is worship, not a backdrop', 'At Masjid Jamek, dress modestly, remove shoes where directed, keep voices low, and respect worshippers and visitor routes. Borrowed coverings are practical hospitality, not costumes; photography should never interrupt prayer or private devotion.', null, '🕌', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "sacred-site conduct", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Masjid Jamek and active mosques", "source_publisher": "malaysia.travel", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.malaysia.travel/explore/masjid-jamek', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'kuala-lumpur', 'market', 'Central Market: craft with context', 'Central Market gathers Malaysian handicrafts, textiles, art, collectibles, and snacks inside a heritage market building. Ask about maker, material, and region, and compare handmade work with mass-produced souvenirs before assigning cultural meaning or value.', null, '🎨', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "fact_review": "pending_human_fact_review", "mutable_details_excluded": true, "operation_recheck": "2027-01-25", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Heritage arts and crafts market", "source_publisher": "malaysia.travel", "source_title": "Official destination market guide", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.malaysia.travel/explore/central-market-kuala-lumpur', 'cc0', 150, 'reference_only'),
