(gen_random_uuid(), 'kyoto', 'phrase', 'お願いします · onegaishimasu', '“onegaishimasu” means “Please; I request this.” Use it when making a polite request or handing over an item.', 'Pronunciation: oh-neh-guy-shee-mas', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Please; I request this", "fact_review": "pending_human_fact_review", "intent": "please", "language": "Japanese", "language_reviewer": "pending_qualified_speaker_review", "original_script": "お願いします", "pronunciation": "oh-neh-guy-shee-mas", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "onegaishimasu", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it when making a polite request or handing over an item.", "usage_context": "Use it when making a polite request or handing over an item.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/japanese.php', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'kyoto', 'phrase', 'これをください · kore o kudasai', '“kore o kudasai” means “This, please.” Use it while indicating a menu item.', 'Pronunciation: koh-reh oh koo-dah-sigh', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "This, please", "fact_review": "pending_human_fact_review", "intent": "ordering", "language": "Japanese", "language_reviewer": "pending_qualified_speaker_review", "original_script": "これをください", "pronunciation": "koh-reh oh koo-dah-sigh", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "kore o kudasai", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it while indicating a menu item.", "usage_context": "Use it while indicating a menu item.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/japanese.php', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'kyoto', 'phrase', 'こんにちは · konnichiwa', '“konnichiwa” means “Hello.” A daytime greeting for arrival or introduction.', 'Pronunciation: kohn-nee-chee-wah', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Hello", "fact_review": "pending_human_fact_review", "intent": "greeting", "language": "Japanese", "language_reviewer": "pending_qualified_speaker_review", "original_script": "こんにちは", "pronunciation": "kohn-nee-chee-wah", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "konnichiwa", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "A daytime greeting for arrival or introduction.", "usage_context": "A daytime greeting for arrival or introduction.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/japanese.php', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'kyoto', 'phrase', 'すみません · Sumimasen', '“Sumimasen” is a flexible polite phrase for excuse me, a light apology, or getting someone’s attention. In crowded Kyoto streets and shops, use it softly before a question or when passing, then make the request clearly.', 'Pronunciation: sumimasen', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Excuse me; I’m sorry", "fact_review": "pending_human_fact_review", "intent": "excuse", "language": "Japanese", "language_reviewer": "pending_qualified_speaker_review", "original_script": "すみません", "pronunciation": "sumimasen", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "sumimasen", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Get attention, pass politely, apologize lightly, or preface a request.", "usage_context": "Useful in shops, transit, and crowded lanes; speak softly and avoid treating Kyoto speech as a costume.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/japanese.php', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'kyoto', 'drink', 'Hōjicha: roasted leaf, softer aroma', 'Kyoto tea shops serve hōjicha made from roasted green tea leaves, producing a nutty aroma and amber cup. It is nonalcoholic and still contains some caffeine; brewing strength varies.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Contains caffeine, generally less than many green teas.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Food and drink in Kyoto", "source_publisher": "Japan National Tourism Organization", "source_title": "A Guide to Japan''s Renowned Green Tea", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.japan.travel/en/ca/inspiration/tea-totalling-a-guide-to-japans-renowned-green-tea/', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'kyoto', 'drink', 'Uji matcha: tea with a long memory', 'Uji is closely tied to Kyoto’s tea heritage: powdered green tea became central to tea ceremony, and Uji offers bowls of matcha alongside sweets. Plain matcha is nonalcoholic but caffeinated; contemporary versions may add dairy or sugar, so ask how yours is prepared.', null, '🍵', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Contains caffeine; sweetened café versions may include dairy.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Tea houses, temples, and contemporary cafés", "source_publisher": "Japan National Tourism Organization", "source_title": "A Guide to Japan''s Renowned Green Tea", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.japan.travel/en/ca/inspiration/tea-totalling-a-guide-to-japans-renowned-green-tea/', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'kyoto', 'etiquette', 'Keep Nishiki''s narrow lane camera-aware', 'Nishiki Market''s lane is narrow and commercially active. Photograph goods from beside the flow, not inside it, and ask shop staff or customers before filming them at close range.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "photography and shared-space courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "residential lanes near temples", "source_publisher": "kyoto.travel", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://kyoto.travel/en/destinations/kyoto-nishiki-food-market/', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'kyoto', 'etiquette', 'Ask the counter''s rhythm at Nishiki Market counters', 'At Nishiki Market, order after deciding where the shop permits food to be eaten. Confirm portion and payment method, then step clear of the narrow counter.', null, '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "ordering, queue, and payment courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Nishiki Market counters", "source_publisher": "kyoto.travel", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://kyoto.travel/en/destinations/kyoto-nishiki-food-market/', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'kyoto', 'etiquette', 'Make space on Kyoto buses and rail platforms', 'On Kyoto buses, board through the signed door and follow the vehicle''s fare instructions. At rail platforms, wait behind markings and keep luggage out of the flow.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "transit and queue courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Kyoto buses and rail platforms", "source_publisher": "kyoto.travel", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://kyoto.travel/en/info/transportation/', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'kyoto', 'etiquette', 'Nishiki’s rule is simple: stop to eat', 'Nishiki Market asks visitors not to eat while walking. Enjoy food at the shop where it was purchased or take it away, keep the narrow lane moving, and remember that the arcade serves residents and workers too.', null, '🚶', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "posted market rule", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Nishiki Market and crowded historic lanes", "source_publisher": "kyoto.travel", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://kyoto.travel/en/destinations/kyoto-nishiki-food-market/', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'kyoto', 'market', 'Nishiki Market: Kyoto’s working kitchen', 'Nishiki’s compact arcade gathers Kyoto vegetables, fish, pickles, yuba, dried goods, knives, and prepared foods. Shop in small groups, leave delivery space, ask before close-up photography, and eat only where the seller directs.', null, '🥬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "fact_review": "pending_human_fact_review", "mutable_details_excluded": true, "operation_recheck": "2027-01-25", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Historic food market arcade", "source_publisher": "kyoto.travel", "source_title": "Official destination market guide", "writer": "Automated Lore editorial research"}'::jsonb, 'https://kyoto.travel/en/destinations/kyoto-nishiki-food-market/', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'lagos', 'phrase', 'Ẹ ṣé', 'Ẹ ṣé (eh-SHEH) means "thank you" in Yoruba and uses a respectful plural form that also works politely with one person. Use it after assistance, directions, or a transaction; Lagos is multilingual, so receive any reply without turning the exchange into a language test.', 'Pronunciation: eh-SHEH', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Thank you", "language": "Yoruba", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "eh-SHEH", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "eh-SHEH", "usage": "Ẹ ṣé (eh-SHEH) means \"thank you\" in Yoruba and uses a respectful plural form that also works politely with one person. Use it after assistance, directions, or a transaction; Lagos is multilingual, so receive any reply without turning the exchange into a language test.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Yoruba_phrasebook', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'lagos', 'phrase', 'Ẹ n lẹ', 'Hello, respectfully addressing more than one person or an elder. Greet before moving to the request.', 'Pronunciation: eh n-leh', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "low", "english": "Hello", "language": "Yorùbá", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "eh n-leh", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A respectful greeting for elders or a group", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Yoruba_phrasebook', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'lagos', 'phrase', 'Jọ̀wọ́', 'Please. Use it to soften a request; tone marks matter in Yorùbá, so keep this reference-only pending speaker review.', 'Pronunciation: jaw-WAW', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "low", "english": "Please", "language": "Yorùbá", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "jaw-WAW", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A polite request", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Yoruba_phrasebook', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'lagos', 'phrase', 'Ẹ má bínú', 'Excuse me or please do not be upset. Use it for a small interruption or apology before explaining what happened.', 'Pronunciation: eh mah bee-NOO', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "low", "english": "Excuse me; sorry", "language": "Yorùbá", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "eh mah bee-NOO", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A polite interruption or minor apology", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Yoruba_phrasebook', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'lagos', 'phrase', 'Mo fẹ́...', 'This means "I would like..." Use it before the item, then point and confirm quantity, spice, or ingredients in a shared language.', 'Pronunciation: moh feh', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "low", "english": "I would like...", "language": "Yorùbá", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "moh feh", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Ordering or requesting an item", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Yoruba_phrasebook', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'lagos', 'phrase', '...wà níbo?', 'Where is ...? Say the place first and show the written destination; confirm the island or mainland location too.', 'Pronunciation: ... wah NEE-boh', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "low", "english": "Where is ...?", "language": "Yorùbá", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "... wah NEE-boh", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Finding a place or transport point", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Yoruba_phrasebook', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'lagos', 'drink', 'Zobo, Gingered Hibiscus', 'Zobo is an alcohol-free hibiscus drink often brightened with ginger, pineapple, citrus, or spice. Sweetness and heat shift from one preparation to another, making it a useful taste of a maker''s balance rather than a beverage with one canonical recipe.', null, '🌺', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://gna.org.gh/2026/03/ghanas-ruby-elixir-celebrating-the-bold-spice-soul-of-sobolo/', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'lagos', 'drink', 'Kunu''s Sweet-Sour Grain', 'Kunu is a nonalcoholic fermented cereal drink found across Nigeria. Grain, spice, sweetness, and texture vary; choose a refrigerated serving and ask about allergens.', null, '🥛', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://doi.org/10.3390/beverages6030053', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'lagos', 'etiquette', 'Respect Before Speed', 'Lagos moves quickly, but courtesy still begins with greeting the person, especially an elder, before the request. Use respectful titles when unsure, keep your tone calm in crowded spaces, and ask before photographing traders, worship, or private life.', null, '🙌', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://tournigeria.gov.ng/lagos-2/', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'lagos', 'etiquette', 'Follow an Elder''s Greeting Cue', 'Open with a greeting and let an elder set the formality before moving to the request. A handshake may be appropriate, but follow the person''s cue rather than copying a bow or gesture.', null, '🤝', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://nepc.gov.ng/importer/doing-business/business-culture/', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'lagos', 'etiquette', 'Confirm Ride Details Before Moving', 'Agree on destination, fare, and payment method before an informal ride begins. Use the app or operator''s live safety features when available.', null, '🚕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://tournigeria.gov.ng/lagos-2/', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'lagos', 'etiquette', 'A Stall Is a Working Counter', 'Keep aisles open, ask before handling goods, and request permission before filming a vendor. Bargain over the item, not the person''s dignity.', null, '🧺', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://tournigeria.gov.ng/lagos-2/', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'lagos', 'market', 'Balogun Is a District, Not an Aisle', 'Balogun Market spreads through the commercial fabric of Lagos Island rather than fitting neatly inside one hall. Go with a plan, keep valuables discreet, follow pedestrian flow, and treat every stall as a workplace where conversation and permission come before the camera.', null, '🧺', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://tournigeria.gov.ng/lagos-2/', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'phrase', 'The Deuce', 'The Deuce is the RTC double-deck transit route serving the Strip and downtown corridor. Use its name with a destination and direction; it is public transit, not a private sightseeing bus.', 'Pronunciation: the doos', '🚌', null, '{"source": "https://www.rtcsnv.com/ways-to-travel/transit-services/transit-guide/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "RTC''s double-deck Strip and downtown bus service", "intent": "navigation_or_local_term", "language": "English", "original": "the Deuce", "pronunciation": "the doos", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "transliteration": null, "usage": "Ask where to board the Deuce and confirm whether you are traveling northbound or southbound."}'::jsonb, 'https://www.rtcsnv.com/ways-to-travel/transit-services/transit-guide/', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'phrase', 'Hello—could you help me?', 'At Fremont Street on foot, let the current exchange finish before greeting and asking one question. Downtown''s Fremont corridor layers vintage Vegas, neon, performers, public art, food, and independent businesses.', 'Pronunciation: spoken as written', '👋', null, '{"source": "https://www.visitlasvegas.com/experience/post/unique-and-exciting-things-to-do-on-fremont-street-and-in-downtown-las-vegas/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "A polite greeting followed by a request for help", "intent": "greeting", "language": "English", "original": "Hello—could you help me?", "pronunciation": "spoken as written", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "usage": "Open with this before asking a vendor at Fremont Street on foot a question."}'::jsonb, 'https://www.visitlasvegas.com/experience/post/unique-and-exciting-things-to-do-on-fremont-street-and-in-downtown-las-vegas/', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'phrase', 'Thanks, I appreciate it', 'When someone clarifies The Deuce, say the complete thank-you before moving on. The Deuce is the RTC double-deck transit route serving the Strip and downtown corridor.', 'Pronunciation: spoken as written', '🙏', null, '{"source": "https://www.rtcsnv.com/ways-to-travel/transit-services/transit-guide/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "A warm thank-you", "intent": "thanks", "language": "English", "original": "Thanks, I appreciate it", "pronunciation": "spoken as written", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "usage": "Use after someone explains The Deuce, a route, or a local custom."}'::jsonb, 'https://www.rtcsnv.com/ways-to-travel/transit-services/transit-guide/', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'phrase', 'Please, when you have a moment', 'When Fremont Street on foot is busy, add this before a nonurgent request and step aside. Explore the five-block Fremont Street Experience, then continue east or toward Main Street to see how the historic center extends beyond the canopy.', 'Pronunciation: spoken as written', '⏳', null, '{"source": "https://www.visitlasvegas.com/experience/post/unique-and-exciting-things-to-do-on-fremont-street-and-in-downtown-las-vegas/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "A request that respects the other person''s pace", "intent": "please", "language": "English", "original": "Please, when you have a moment", "pronunciation": "spoken as written", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "usage": "Use at a busy Fremont Street on foot counter before a non-urgent question."}'::jsonb, 'https://www.visitlasvegas.com/experience/post/unique-and-exciting-things-to-do-on-fremont-street-and-in-downtown-las-vegas/', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'phrase', 'Excuse me—could you help me?', 'For The Deuce help in Las Vegas, move aside and name the destination. Use its name with a destination and direction; it is public transit, not a private sightseeing bus.', 'Pronunciation: spoken as written', '🙋', null, '{"source": "https://www.rtcsnv.com/ways-to-travel/transit-services/transit-guide/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "A polite way to get attention and request help", "intent": "help_excuse", "language": "English", "original": "Excuse me—could you help me?", "pronunciation": "spoken as written", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "usage": "Use before asking which The Deuce service or direction you need."}'::jsonb, 'https://www.rtcsnv.com/ways-to-travel/transit-services/transit-guide/', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'phrase', 'Could I have a zero-proof cocktail, please?', 'Order by name and clarify dairy, caffeine, sweetener, or alcohol-free needs before preparation. Las Vegas bars increasingly treat spirit-free drinks as composed beverages, not juice afterthoughts.', 'Pronunciation: spoken as written', '🥤', null, '{"source": "https://vegas.eater.com/maps/where-best-mocktails-virgin-cocktails-non-alcohol-las-vegas"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "A polite order for a zero-proof cocktail", "intent": "ordering", "language": "English", "original": "Could I have a zero-proof cocktail, please?", "pronunciation": "spoken as written", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "usage": "Use at the counter, then state zero-proof, sweetness, dairy, or caffeine needs plainly."}'::jsonb, 'https://vegas.eater.com/maps/where-best-mocktails-virgin-cocktails-non-alcohol-las-vegas', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'drink', 'A deliberate zero-proof drink', 'Las Vegas bars increasingly treat spirit-free drinks as composed beverages, not juice afterthoughts. Ask for zero-proof or nonalcoholic, describe flavors you like, and confirm ingredients if avoiding even trace alcohol matters.', null, '🍹', null, '{"source": "https://vegas.eater.com/maps/where-best-mocktails-virgin-cocktails-non-alcohol-las-vegas"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://vegas.eater.com/maps/where-best-mocktails-virgin-cocktails-non-alcohol-las-vegas', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'drink', 'A citrus-forward mocktail', 'Las Vegas bars increasingly treat alcohol-free cocktails as composed drinks. Ask for a citrus-forward option, confirm it contains no bitters or other alcohol, and learn which syrup or garnish is made in-house rather than settling for a vague ''virgin'' label.', null, '🫖', null, '{"source": "https://vegas.eater.com/maps/where-best-mocktails-virgin-cocktails-non-alcohol-las-vegas"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://vegas.eater.com/maps/where-best-mocktails-virgin-cocktails-non-alcohol-las-vegas', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'etiquette', 'Keep Fremont moving', 'Fremont Street is a pedestrian mall and a workplace for registered performers. Keep entrances and walkways open, give designated performance circles room, never pressure a performer or passerby, and remember that commercial filming requires permission even though personal photography is allowed.', null, '🚶', null, '{"source": "https://secure3.lasvegasnevada.gov/buskerpermit/cityordinance.aspx"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://secure3.lasvegasnevada.gov/buskerpermit/cityordinance.aspx', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'etiquette', 'Confirm The Deuce before boarding', 'Board The Deuce after riders exit; name the line or direction before the doorway. The Deuce is the RTC double-deck transit route serving the Strip and downtown corridor.', null, '🚌', null, '{"source": "https://www.rtcsnv.com/ways-to-travel/transit-services/transit-guide/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.rtcsnv.com/ways-to-travel/transit-services/transit-guide/', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'etiquette', 'Ask about a zero-proof cocktail', 'Ask how a zero-proof cocktail is made here, especially when caffeine, dairy, sugar, or alcohol matters. Ask for zero-proof or nonalcoholic, describe flavors you like, and confirm ingredients if avoiding even trace alcohol matters.', null, '🥤', null, '{"source": "https://vegas.eater.com/maps/where-best-mocktails-virgin-cocktails-non-alcohol-las-vegas"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://vegas.eater.com/maps/where-best-mocktails-virgin-cocktails-non-alcohol-las-vegas', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'etiquette', 'Share the space', 'At Fremont Street on foot, keep aisles and pickup areas clear; ask before close-up photos. Downtown''s Fremont corridor layers vintage Vegas, neon, performers, public art, food, and independent businesses.', null, '🧺', null, '{"source": "https://www.visitlasvegas.com/experience/post/unique-and-exciting-things-to-do-on-fremont-street-and-in-downtown-las-vegas/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.visitlasvegas.com/experience/post/unique-and-exciting-things-to-do-on-fremont-street-and-in-downtown-las-vegas/', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'las-vegas', 'market', 'Fremont Street on foot', 'Downtown''s Fremont corridor layers vintage Vegas, neon, performers, public art, food, and independent businesses. Explore the five-block Fremont Street Experience, then continue east or toward Main Street to see how the historic center extends beyond the canopy.', null, '🎰', null, '{"source": "https://www.visitlasvegas.com/experience/post/unique-and-exciting-things-to-do-on-fremont-street-and-in-downtown-las-vegas/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.visitlasvegas.com/experience/post/unique-and-exciting-things-to-do-on-fremont-street-and-in-downtown-las-vegas/', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'lima', 'phrase', 'La cuenta, por favor', 'La cuenta, por favor (lah KWEN-tah por fah-VOR) means "the bill, please" in Spanish. Use it when you are ready to pay at a restaurant or cafe; make eye contact or raise a hand gently rather than calling across the room.', 'Pronunciation: lah KWEN-tah por fah-VOR', '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "The bill, please", "language": "Peruvian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "lah KWEN-tah por fah-VOR", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "lah KWEN-tah por fah-VOR", "usage": "La cuenta, por favor (lah KWEN-tah por fah-VOR) means \"the bill, please\" in Spanish. Use it when you are ready to pay at a restaurant or cafe; make eye contact or raise a hand gently rather than calling across the room.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'lima', 'phrase', 'Buenos días', 'Good morning. Use it before asking a question, ordering, or beginning a transaction.', 'Pronunciation: BWEH-nohs DEE-ahs', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Good morning", "language": "Peruvian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "BWEH-nohs DEE-ahs", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A respectful morning greeting", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'lima', 'phrase', 'Muchas gracias', 'Thank you very much. Use it after directions, service, or patient help with a menu or route.', 'Pronunciation: MOO-chahs GRAH-syahs', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Thank you very much", "language": "Peruvian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "MOO-chahs GRAH-syahs", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Warm everyday thanks", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'lima', 'phrase', 'Por favor', 'Please. Add it to a request and keep the request specific in a busy market or cafe.', 'Pronunciation: por fah-VOR', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Please", "language": "Peruvian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "por fah-VOR", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A polite request marker", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'lima', 'phrase', 'Disculpe, ¿me puede ayudar?', 'Excuse me, can you help me? Use it before asking about a stop, entrance, address, or service.', 'Pronunciation: dees-KOOL-peh, meh PWEH-deh ah-yoo-DAR', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Excuse me, can you help me?", "language": "Peruvian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "dees-KOOL-peh, meh PWEH-deh ah-yoo-DAR", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Getting attention and asking for help", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'lima', 'phrase', '¿Dónde queda...?', 'Where is ...? Add the destination and show the address, since similar street names may span different districts.', 'Pronunciation: DON-deh KEH-dah', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Where is ...?", "language": "Peruvian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "DON-deh KEH-dah", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Finding a place or district", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'lima', 'drink', 'Chicha Morada, Lima Purple', 'Chicha morada is an alcohol-free drink made from purple corn and commonly scented with fruit and spice. Lima versions vary in sweetness, citrus, cinnamon, and clove; try it with food, and do not confuse it with fermented chicha de jora.', null, '💜', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.peru.travel/gastronomy/en/peruvian-cuisine/cuisine-of-lima.html', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'lima', 'drink', 'Emoliente at the Street Cart', 'Emoliente is a warm herbal and grain-based drink whose ingredients vary by vendor. Ask what is in the pot, especially for allergies, and choose a freshly served cup.', null, '🫖', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.peru.travel/gastronomy/en/peruvian-cuisine/cuisine-of-lima.html', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'lima', 'etiquette', 'Greet Before the Question', 'Begin a request with buenos días, buenas tardes, or buenas noches, and use señor, señora, or usted when formality is unclear. In crowded public spaces, permiso is the courteous way through; warmth and patience work better than volume.', null, '🤝', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/peruvian-culture/peruvian-culture-greetings', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'lima', 'etiquette', 'Give the Metropolitano Platform Room', 'At Metropolitano platforms, let riders leave before boarding and move away from the doors once inside. Confirm the corridor and transfer before committing, since a missed stop can change the route substantially.', null, '🚌', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.gob.pe/atu', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'lima', 'etiquette', 'A Service Charge Is Not a Guess', 'Read the bill before adding a tip and ask if a charge is unclear. Do not assume another country''s percentage applies automatically.', null, '💵', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/peruvian-culture/peruvian-culture-etiquette', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'lima', 'etiquette', 'Convents and Churches Set the Frame', 'Follow dress, silence, and photography signs, and pause sightseeing during worship. Historic architecture remains an active sacred space.', null, '⛪', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://whc.unesco.org/en/list/500/', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'lima', 'market', 'Surquillo Through One Ingredient', 'Surquillo''s markets offer a practical introduction to Peru''s extraordinary range of fruit, potatoes, chiles, herbs, seafood, and grains. Choose one unfamiliar ingredient, ask its name and use, and keep the exchange respectful by buying before requesting an extended lesson or portrait.', null, '🌶️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.peru.travel/lafinalenlima/conoce-lima/imperdibles.html', 'cc0', 150, 'reference_only'),
