(gen_random_uuid(), 'manchester', 'etiquette', 'Enter Manchester Cathedral as a guest', 'At Manchester Cathedral, follow posted rules, silence devices, and ask before photographing people or services. Its role as an active Anglican cathedral comes before a visitor''s photograph.', 'Reference lead: Wikivoyage', '🕯️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "See", "source_title": "Manchester travel guide: See", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Manchester#See', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'manchester', 'etiquette', 'Northern Quarter is a neighborhood', 'In Northern Quarter, keep doorways clear, lower late-night voices, and use public viewpoints rather than residential windows or courtyards. Manchester remains lived-in beyond its landmarks.', 'Reference lead: Wikivoyage', '🏘️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Respect", "source_title": "Manchester travel guide: Respect", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Manchester#Respect', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'manchester', 'market', 'Manchester Arndale Market', 'Inside the city-center complex, this market combines fish, meat, produce, services, and food counters shaped by Manchester’s many communities. Look past the surrounding retail mall for its independent traders.', 'Reference lead: Wikivoyage', '🌶️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Buy", "source_title": "Manchester travel guide: Buy", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Manchester#Buy', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'phrase', 'بشحال؟ · Bshhal?', 'بشحال؟ (bshhal?) means "how much?" in Moroccan Arabic. Use it to ask a price after greeting the seller and showing genuine interest; if bargaining is appropriate, keep the exchange good-humored and accept a final no without pressure.', 'Pronunciation: bshhal?', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "How much?", "language": "Moroccan Arabic (Darija)", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "bshhal?", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "bshhal?", "usage": "بشحال؟ (bshhal?) means \"how much?\" in Moroccan Arabic. Use it to ask a price after greeting the seller and showing genuine interest; if bargaining is appropriate, keep the exchange good-humored and accept a final no without pressure.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moroccan_Arabic_phrasebook', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'phrase', 'سلام · Salam', 'Hello or peace. Use it before asking a price, entering a small shop, or beginning a conversation.', 'Pronunciation: sah-LAHM', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Hello; peace", "language": "Moroccan Arabic (Darija)", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "sah-LAHM", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "An everyday greeting", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moroccan_Arabic_phrasebook', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'phrase', 'شكرا · Shukran', 'Thank you. Use it after help, service, or a completed purchase; a brief thanks closes the exchange warmly.', 'Pronunciation: SHOOK-rahn', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Thank you", "language": "Moroccan Arabic (Darija)", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "SHOOK-rahn", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Everyday thanks", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moroccan_Arabic_phrasebook', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'phrase', 'عفاك · ʿAfak', 'Please. Add it to a request; the displayed form and register still require qualified local review.', 'Pronunciation: ah-FAHK', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "low", "english": "Please", "language": "Moroccan Arabic (Darija)", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "ah-FAHK", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A polite request", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moroccan_Arabic_phrasebook', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'phrase', 'سمح ليا · Smeḥ liya', 'Excuse me or forgive me. Use it to pass, interrupt gently, or correct a small mistake.', 'Pronunciation: smeh LEE-yah', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "low", "english": "Excuse me; forgive me", "language": "Moroccan Arabic (Darija)", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "smeh LEE-yah", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A minor apology or polite interruption", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moroccan_Arabic_phrasebook', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'phrase', 'فين...؟ · Fin...?', 'Where is ...? Add the place name and show it in writing; medina lanes may have several locally used landmarks.', 'Pronunciation: feen', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Where is ...?", "language": "Moroccan Arabic (Darija)", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "feen", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Finding a place or landmark", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moroccan_Arabic_phrasebook', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'drink', 'Mint Tea, Poured With Welcome', 'Moroccan mint tea is an alcohol-free blend of green tea, mint, and sugar, often poured from height to aerate the glass. Sweetness and ritual vary by setting; receive a host''s preparation as hospitality, and ask rather than assume if you prefer less sugar.', null, '🫖', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.visitmorocco.com/en/blog/time-moroccan-tea', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'drink', 'Orange Juice at the Square', 'Fresh orange juice is a zero-proof pause amid the square''s motion. Choose a busy stand, watch the fruit being pressed, and ask whether sugar or ice is added.', null, '🍊', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.visitmorocco.com/en/travel/marrakech/shopping', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'etiquette', 'Permission Before the Portrait', 'The medina is a neighborhood and workplace, not an open set. Greet before asking, request permission before photographing people or performances, dress thoughtfully near religious spaces, and do not enter a mosque or sacred area unless visitor access is clearly welcomed.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.lonelyplanet.com/articles/things-to-know-before-traveling-to-morocco', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'etiquette', 'Bargain Only Where It Is Invited', 'In a souk, begin with a greeting, ask the price, and negotiate calmly if the seller engages. Fixed-price shops and displayed menus are not invitations to haggle.', null, '💵', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.visitmorocco.com/en/travel/marrakech/shopping', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'etiquette', 'The Medina Lane Is Shared', 'Walk to one side, listen for carts and scooters, and pause outside the traffic flow before checking a map. Doorways are not waiting areas.', null, '🚶', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.lonelyplanet.com/articles/things-to-know-before-traveling-to-morocco', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'etiquette', 'Sacred Entrances Have Their Own Rules', 'Do not assume a mosque is open to non-Muslim visitors. Read the entrance guidance, dress modestly, and never photograph through a doorway into prayer.', null, '🕌', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.lonelyplanet.com/articles/things-to-know-before-traveling-to-morocco', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'marrakech', 'market', 'Read the Souks by Craft', 'Marrakech''s souks become more legible when you follow leather, metal, textiles, spices, wood, and their makers. Ask where and how an object was made, compare without belittling, and bargain only when the seller signals that it is part of the exchange.', null, '🪔', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.visitmorocco.com/en/travel/marrakech/shopping', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'mecca', 'phrase', 'أريد هذا من فضلك · urīdu hādhā min faḍlik', '“urīdu hādhā min faḍlik” means “I would like this, please.” Point only after saying the phrase so the request stays clear and courteous.', 'Pronunciation: oo-ree-doo haa-tha min fad-lik', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "I would like this, please", "fact_review": "pending_human_fact_review", "intent": "ordering", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "أريد هذا من فضلك", "pronunciation": "oo-ree-doo haa-tha min fad-lik", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "urīdu hādhā min faḍlik", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Point only after saying the phrase so the request stays clear and courteous.", "usage_context": "Point only after saying the phrase so the request stays clear and courteous.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/arabic.php', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'mecca', 'phrase', 'أين ...؟ · ayna ...?', '“ayna ...?” means “Where is ...?” Place a destination after ayna, or show the written name while asking.', 'Pronunciation: ay-na', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Where is ...?", "fact_review": "pending_human_fact_review", "intent": "navigation", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "أين ...؟", "pronunciation": "ay-na", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "ayna ...?", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Place a destination after ayna, or show the written name while asking.", "usage_context": "Place a destination after ayna, or show the written name while asking.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/arabic.php', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'mecca', 'phrase', 'شكراً · Shukran', '“Shukran” means “thank you” in Arabic and is useful for practical help, service, or directions. Mecca welcomes Muslims from many language communities, so keep communication patient and never mistake one Arabic variety for everyone’s first language.', 'Pronunciation: shukran', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Thank you.", "fact_review": "pending_human_fact_review", "intent": "thanks", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "شكراً", "pronunciation": "shukran", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "shukran", "source_publisher": "visitsaudi.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Express thanks after practical help, service, or directions.", "usage_context": "A simple courtesy in a globally multilingual pilgrimage city; avoid using sacred formulas as tourist performance.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.visitsaudi.com/content/dam/saudi-tourism/media/guides/saudi-series-culture-english.pdf', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'mecca', 'phrase', 'لو سمحت · law samaḥt', '“law samaḥt” means “Excuse me; if you please.” Use it to get attention or ask for help without calling across a room.', 'Pronunciation: law sa-maht', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Excuse me; if you please", "fact_review": "pending_human_fact_review", "intent": "excuse", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "لو سمحت", "pronunciation": "law sa-maht", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "law samaḥt", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it to get attention or ask for help without calling across a room.", "usage_context": "Use it to get attention or ask for help without calling across a room.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/arabic.php', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'mecca', 'phrase', 'مرحباً · marḥaban', '“marḥaban” means “Hello.” Use it for a simple daytime greeting; a longer religious greeting may be answered in kind.', 'Pronunciation: mar-ha-ban', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Hello", "fact_review": "pending_human_fact_review", "intent": "greeting", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "مرحباً", "pronunciation": "mar-ha-ban", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "marḥaban", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it for a simple daytime greeting; a longer religious greeting may be answered in kind.", "usage_context": "Use it for a simple daytime greeting; a longer religious greeting may be answered in kind.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/arabic.php', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'mecca', 'phrase', 'من فضلك · min faḍlak / min faḍlik', '“min faḍlak / min faḍlik” means “Please.” Add it to a request; the ending traditionally varies with the person addressed.', 'Pronunciation: min fad-lak / min fad-lik', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Please", "fact_review": "pending_human_fact_review", "intent": "please", "language": "Arabic", "language_reviewer": "pending_qualified_speaker_review", "original_script": "من فضلك", "pronunciation": "min fad-lak / min fad-lik", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "min faḍlak / min faḍlik", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Add it to a request; the ending traditionally varies with the person addressed.", "usage_context": "Add it to a request; the ending traditionally varies with the person addressed.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/arabic.php', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'mecca', 'drink', 'Saudi coffee: small pours, shared pause', 'Lightly roasted Arabic coffee, often fragrant with cardamom, accompanies hospitality across Saudi Arabia. It is nonalcoholic and caffeinated; in Mecca, receive it as refreshment without turning a shared custom into a photo prop.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Caffeinated; spice blend varies.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Food and drink in Mecca", "source_publisher": "ich.unesco.org", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://ich.unesco.org/en/RL/arabic-coffee-a-symbol-of-generosity-01074', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'mecca', 'drink', 'Zamzam: sacred water, not a novelty drink', 'For Muslims, Zamzam is sacred water bound to pilgrimage and the Grand Mosque. Use designated drinking containers, do not use them for ablution, take only what is appropriate, and follow current mosque and pilgrimage guidance.', null, '💧', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Sacred water; handling is governed by official site guidance.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Grand Mosque and Muslim pilgrimage", "source_publisher": "haj.gov.sa", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://haj.gov.sa/en/Makkah-Al-Mukarramah/About-the-Grand-Mosque?masjidHaramInfoTab=mosque-services', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'mecca', 'etiquette', 'Know who may enter the Holy Mosque', 'Saudi Arabia''s official tourist-visa terms state that non-Muslims may not enter the Holy Mosque or its premises in Makkah. Travelers must respect the restriction and follow current official route signs.', null, '🕌', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "religious access restriction", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "the Holy Mosque and its premises in Makkah", "source_publisher": "Official Saudi tourist visa service", "source_title": "Saudi eVisa terms and conditions", "writer": "Automated Lore editorial research"}'::jsonb, 'https://visa.visitsaudi.com/Home/TermsConditions', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'mecca', 'etiquette', 'Ask the counter''s rhythm at Souq Al Diyafa counters', 'At Souq Al Diyafa, identify the ordering line, confirm the item and quantity, and ask which payment method the seller accepts. Complete the transaction away from pilgrim circulation routes.', null, '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "ordering, queue, and payment courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Souq Al Diyafa counters", "source_publisher": "book.visitsaudi.com", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://book.visitsaudi.com/product/eb4439fd-41d3-4440-bee7-dc376d74dbab?locale=en', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'mecca', 'etiquette', 'Make space on pilgrim transport and signed walking routes', 'Pilgrim transport and walking routes may change with crowd controls. Travel light, follow officials and one-way signs, and never stop in a moving corridor to regroup.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "transit and queue courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "pilgrim transport and signed walking routes", "source_publisher": "haj.gov.sa", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://haj.gov.sa/-/media/Project/HAJJ/Awareness-Guides/UMRAH-VISIT-GUIDE/English/EN-Umrah-visit-Guide.pdf', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'mecca', 'etiquette', 'Worship and pilgrim safety come first', 'In the Grand Mosque and holy sites, avoid pushing, loud calls, obstructive photography, and stopping in circulation routes. Keep devices quiet, follow officials, and center prayer and pilgrim safety rather than documenting your own presence.', null, '🕋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "official sacred-site and crowd-safety conduct", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Grand Mosque and Hajj or Umrah holy sites", "source_publisher": "haj.gov.sa", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://haj.gov.sa/-/media/Project/HAJJ/Awareness-Guides/UMRAH-VISIT-GUIDE/English/EN-Umrah-visit-Guide.pdf', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'mecca', 'market', 'Souq Al Diyafa: practical shopping after worship', 'Souq Al Diyafa is a commercial stop, distinct from Mecca’s sacred rites. Shop after religious obligations, keep bags out of pilgrim routes, compare quality and origin claims, and never frame a purchase as spiritual merit.', null, '🛍️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "fact_review": "pending_human_fact_review", "mutable_details_excluded": true, "operation_recheck": "2027-01-25", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Pilgrimage-city commercial market", "source_publisher": "book.visitsaudi.com", "source_title": "Official destination market guide", "writer": "Automated Lore editorial research"}'::jsonb, 'https://book.visitsaudi.com/product/eb4439fd-41d3-4440-bee7-dc376d74dbab?locale=en', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'medellin', 'phrase', 'Con mucho gusto', 'Con mucho gusto (kohn MOO-choh GOOS-toh) means "with pleasure" and is a warm Colombian reply to thanks. Use it after someone says gracias, or listen for it from others; its hospitality lands best when you answer with the same unhurried courtesy.', 'Pronunciation: kohn MOO-choh GOOS-toh', '🙂', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "With pleasure; you''re welcome", "language": "Colombian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "kohn MOO-choh GOOS-toh", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "kohn MOO-choh GOOS-toh", "usage": "Con mucho gusto (kohn MOO-choh GOOS-toh) means \"with pleasure\" and is a warm Colombian reply to thanks. Use it after someone says gracias, or listen for it from others; its hospitality lands best when you answer with the same unhurried courtesy.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/colombian-culture/colombian-culture-communication', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'medellin', 'phrase', 'Buenos días', 'Good morning. Use it before asking a price, route, or favor; the greeting makes the request less abrupt.', 'Pronunciation: BWEH-nohs DEE-ahs', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Good morning", "language": "Colombian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "BWEH-nohs DEE-ahs", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A respectful morning greeting", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'medellin', 'phrase', 'Por favor', 'Please. Add it to a clear request and begin with usted until invited to speak more familiarly.', 'Pronunciation: por fah-VOR', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Please", "language": "Colombian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "por fah-VOR", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A polite request marker", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'medellin', 'phrase', 'Disculpe, ¿me puede ayudar?', 'Excuse me, can you help me? Use it before asking about a metro transfer, address, or service.', 'Pronunciation: dees-KOOL-peh, meh PWEH-deh ah-yoo-DAR', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Excuse me, can you help me?", "language": "Colombian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "dees-KOOL-peh, meh PWEH-deh ah-yoo-DAR", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Getting attention and asking for help", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'medellin', 'phrase', 'Quisiera..., por favor', 'I would like..., please. Use it when ordering and confirm ingredients or size rather than relying on a pointed gesture.', 'Pronunciation: kee-SYEH-rah, por fah-VOR', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "I would like..., please", "language": "Colombian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "kee-SYEH-rah, por fah-VOR", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Ordering food or drink", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'medellin', 'phrase', '¿Dónde queda...?', 'Where is ...? Add the place and ask which exit, cable line, or neighborhood entrance is best.', 'Pronunciation: DON-deh KEH-dah', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Where is ...?", "language": "Colombian Spanish", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "DON-deh KEH-dah", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Finding a place or transfer", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Spanish_phrasebook', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'medellin', 'drink', 'Aguapanela in the Mountain Air', 'Warm aguapanela is an alcohol-free panela drink that suits Medellín''s cooler viewpoints and rainy pauses; local servings may come with cheese, lime, or neither. Ask how it is served before ordering, and treat the pairing as everyday regional comfort rather than a dare.', null, '🍯', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.medellin.travel/entertainment/?lang=en', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'medellin', 'drink', 'Tinto, Neighborhood by Neighborhood', 'Tinto is a small black coffee, often sweetened. Ask for sin azúcar if preferred and compare how roast and serving style change between counters.', null, '☕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.medellin.travel/gastronomy/?lang=en', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'medellin', 'etiquette', 'Warm Does Not Mean Instantly Familiar', 'Medellín''s conversational warmth still leaves room for respectful distance. Start with a greeting and usted, follow the other person''s lead on tú, and avoid questions that reduce the city''s residents to past violence or a single television narrative.', null, '🤝', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/colombian-culture/colombian-culture-etiquette', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'medellin', 'etiquette', 'The Metro Culture Is Shared Care', 'Queue, let riders exit, keep cars and platforms clean, and follow staff guidance. The system''s civic culture depends on each rider.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.metrodemedellin.gov.co/cultura-metro/', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'medellin', 'etiquette', 'Let Neighborhood Voices Lead', 'Choose community-tourism experiences created and hosted with residents. Ask how the route supports neighborhood businesses and keeps benefits in the territory, then let residents'' own voices frame local change rather than supplying a visitor''s before-and-after story.', null, '🏘️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.medellin.gov.co/es/sala-de-prensa/noticias/turismo-comunitario-la-esencia-de-medellin-que-transforma-territorios/', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'medellin', 'etiquette', 'Escalators Keep a Moving Edge', 'Stand to the side indicated by local flow, hold the rail, and step away from the landing before checking directions.', null, '🚶', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.metrodemedellin.gov.co/cultura-metro/', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'medellin', 'market', 'The City Through Its Food Markets', 'Medellín''s traditional plazas and newer gastronomic markets reveal different sides of paisa food, from produce and grains to prepared dishes and contemporary kitchens. Ask where ingredients come from, taste across formats, and do not mistake a polished food hall for the whole market culture.', null, '🫘', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.medellin.travel/gastronomy/?lang=en', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'phrase', 'Could I get a long black, please?', '"Could I get a long black, please?" is a clear Australian English cafe order for espresso over hot water. Use it at the counter, add your milk preference only if wanted, and finish with thanks; directness lands best when it stays courteous.', 'Pronunciation: could I get a long black, please?', '☕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "An order for espresso with hot water", "language": "Australian English", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "could I get a long black, please?", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "could I get a long black, please?", "usage": "\"Could I get a long black, please?\" is a clear Australian English cafe order for espresso over hot water. Use it at the counter, add your milk preference only if wanted, and finish with thanks; directness lands best when it stays courteous.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.australia.com/en/things-to-do/food-and-drinks/australian-coffee-cheat-sheet.html', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'phrase', 'G''day', 'Hello. Use the relaxed one-beat greeting without pushing an exaggerated accent.', 'Pronunciation: guh-DAY', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: guh-DAY", "english": "Hello", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "guh-DAY", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "An informal greeting", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/australian-culture/australian-culture-greetings', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'phrase', 'Thanks, I appreciate it', 'Use this after help, directions, or service; stress appreciate lightly.', 'Pronunciation: thanks, eye uh-PREE-shee-ate it', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: thanks, eye uh-PREE-shee-ate it", "english": "Thanks, I appreciate it", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "thanks, eye uh-PREE-shee-ate it", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Warm everyday thanks", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/appreciate', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'phrase', 'Could you please...?', 'Use this for a polite request at a cafe, shop, hotel, or station.', 'Pronunciation: could-yuh pleez', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: could-yuh pleez", "english": "Could you please...?", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "could-yuh pleez", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A polite request", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/please', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'phrase', 'Excuse me, could you help?', 'Use this before asking for assistance, then name the stop, lane, building, or accessibility need.', 'Pronunciation: ex-KYOOZ mee, could-yuh help', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: ex-KYOOZ mee, could-yuh help", "english": "Excuse me, could you help?", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "ex-KYOOZ mee, could-yuh help", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Getting attention and asking for help", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dictionary.cambridge.org/dictionary/english/excuse-me', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'phrase', 'Which tram for...?', 'Use this at a stop and show the destination; route numbers can share tracks before separating.', 'Pronunciation: which tram fuh', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "editorial_attribution": "Spoken guidance: which tram fuh", "english": "Which tram for...?", "language": "Australian English", "language_review_state": "pending_human_editorial_review", "pronunciation": "which tram fuh", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Choosing the correct tram", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.ptv.vic.gov.au/journey', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'drink', 'The Long Black Test', 'A long black leaves milk out of the equation, making it an alcohol-free way to taste a Melbourne roaster''s espresso and water balance. Sip before adding anything; if you prefer less intensity, ask for extra hot water rather than assuming every cafe pours it identically.', null, '☕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.australia.com/en/things-to-do/food-and-drinks/australian-coffee-cheat-sheet.html', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'drink', 'Market Juice by One Ingredient', 'At Queen Victoria Market, let one seasonal fruit lead a zero-proof juice. Ask which stall ingredient is at its peak, then check whether the maker adds dairy, sweetener, or another fruit before choosing.', null, '🧃', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://whatson.melbourne.vic.gov.au/things-to-do/queen-victoria-market', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'etiquette', 'Let the Tram Empty First', 'On trams and trains, wait for passengers to exit before boarding, move away from doors, and offer priority seating when needed. Melbourne''s public spaces run on small acts of awareness: keep audio private, queue in order, and do not stop suddenly in narrow lanes.', null, '🚋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/australian-culture/australian-culture-etiquette', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'etiquette', 'Touch On, Let Off, Move Down', 'Use the current fare method, let riders exit, and move away from tram doors. Recheck the free-tram boundary before relying on it.', null, '🚋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.ptv.vic.gov.au/tickets/myki', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'etiquette', 'The Laneway Is Still a Workplace', 'Keep service doors and foot traffic clear, ask before photographing staff, and do not move cafe furniture for a composition.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://culturalatlas.sbs.com.au/australian-culture/australian-culture-etiquette', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'etiquette', 'Street Art Has Authors', 'Photograph from public space without touching the work, credit an artist when identified, and do not assume every wall is a legal canvas.', null, '🎨', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://whatson.melbourne.vic.gov.au/things-to-do/walks/street-art', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'melbourne', 'market', 'Queen Victoria Market by Ingredient', 'Read Queen Victoria Market through one ingredient at a time: cheese, spice, fruit, seafood, bread, or the migration story behind a prepared dish. Ask traders what is seasonal, keep aisles moving, and give the market''s layered history more attention than a single famous snack.', null, '🍋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://whatson.melbourne.vic.gov.au/things-to-do/queen-victoria-market', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'phrase', 'Buenos días', 'Use buenos días as a morning greeting before a question; switch to buenas tardes later in the day. Follow with disculpe when asking an unfamiliar adult for help.', 'Pronunciation: BWEH-nohs DEE-ahs', '👋', null, '{"context_source": "https://mexicocity.cdmx.gob.mx/e/basics-for-mexico-city-travel/?lang=en", "source": "https://dle.rae.es/bueno"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Good morning", "intent": "greeting", "language": "Spanish", "original": "Buenos días", "pronunciation": "BWEH-nohs DEE-ahs", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use in the morning at a shop, café, or La Merced counter."}'::jsonb, 'https://dle.rae.es/bueno', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'phrase', 'Gracias', 'Use gracias after directions, service, or a purchase. Add a brief reason only when it helps clarify what you appreciated; one sincere word is enough.', 'Pronunciation: GRAH-syahs', '🙏', null, '{"context_source": "https://mexicocity.cdmx.gob.mx/e/basics-for-mexico-city-travel/?lang=en", "source": "https://dle.rae.es/gracias"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Thank you", "intent": "thanks", "language": "Spanish", "original": "Gracias", "pronunciation": "GRAH-syahs", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use after directions, service, or a short exchange."}'::jsonb, 'https://dle.rae.es/gracias', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'phrase', 'Por favor', 'Place por favor before or after a concise request, and pair it with a greeting instead of using it alone. The phrase adds courtesy; it does not replace listening for the answer.', 'Pronunciation: por fah-VOR', '🤲', null, '{"context_source": "https://mexicocity.cdmx.gob.mx/venues/la-merced/?lang=en", "source": "https://dle.rae.es/favor"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Please", "intent": "please", "language": "Spanish", "original": "Por favor", "pronunciation": "por fah-VOR", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Add to a request or order."}'::jsonb, 'https://dle.rae.es/favor', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'phrase', 'Disculpe, ¿me puede ayudar?', 'Use disculpe to get attention before a brief request. The verb form addresses usted; listen for whether the other person keeps that register or invites a more informal tone.', 'Pronunciation: dees-KOOL-peh, meh PWEH-deh ah-yoo-DAR', '🙋', null, '{"context_source": "https://mexicocity.cdmx.gob.mx/e/basics-for-mexico-city-travel/?lang=en", "source": "https://dle.rae.es/disculpar"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Excuse me, can you help me?", "intent": "help_excuse", "language": "Spanish", "original": "Disculpe, ¿me puede ayudar?", "pronunciation": "dees-KOOL-peh, meh PWEH-deh ah-yoo-DAR", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use with an unfamiliar adult before showing a map or destination."}'::jsonb, 'https://dle.rae.es/disculpar', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'phrase', 'Quisiera un atole, por favor', 'Use quisiera for a courteous order, then name the atole flavor and clarify sweetness or dairy needs. Keep the item visible if pronunciation becomes a barrier.', 'Pronunciation: kee-SYEH-rah oon ah-TOH-leh; por fah-VOR', '🥤', null, '{"context_source": "https://www.gob.mx/inpi/articulos/el-atole-bebidas-tradicionales-de-los-pueblos-indigenas", "source": "https://dle.rae.es/querer"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "I would like an atole, please", "intent": "ordering", "language": "Spanish", "original": "Quisiera un atole, por favor", "pronunciation": "kee-SYEH-rah oon ah-TOH-leh; por fah-VOR", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use at a counter; then ask which flavor is available."}'::jsonb, 'https://dle.rae.es/querer', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'phrase', '¿Me puede indicar el Metro?', 'Use this complete question when a Metro entrance is not obvious. Listen for a street, corner, or station name, repeat it back, and step away from the flow before checking your route.', 'Pronunciation: meh PWEH-deh een-dee-KAR el MEH-troh', '🧭', null, '{"context_source": "https://mexicocity.cdmx.gob.mx/venues/la-merced/?lang=en", "source": "https://mexicocity.cdmx.gob.mx/e/basics-for-mexico-city-travel/?lang=en"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Can you point me toward the Metro?", "intent": "navigation", "language": "Spanish", "original": "¿Me puede indicar el Metro?", "pronunciation": "meh PWEH-deh een-dee-KAR el MEH-troh", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use with disculpe before the question and gracias afterward."}'::jsonb, 'https://mexicocity.cdmx.gob.mx/e/basics-for-mexico-city-travel/?lang=en', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'drink', 'Atole', 'Atole is a warm, pre-Hispanic corn-based drink with many regional forms, from plain nixtamal to versions flavored with cacao, vanilla, fruit, or cinnamon. In Mexico City it commonly accompanies tamales; ask which flavor is in the pot.', null, '🌽', null, '{"source": "https://www.gob.mx/inpi/articulos/el-atole-bebidas-tradicionales-de-los-pueblos-indigenas"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.gob.mx/inpi/articulos/el-atole-bebidas-tradicionales-de-los-pueblos-indigenas', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'drink', 'Agua fresca at La Merced', 'At La Merced, ask which agua fresca is in the container today and whether it contains added sugar. Fruit, seed, grain, and flower versions differ; ordering by the named flavor turns a cold nonalcoholic drink into a small vocabulary lesson.', null, '🫖', null, '{"source": "https://mexicocity.cdmx.gob.mx/venues/la-merced/?lang=en"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://mexicocity.cdmx.gob.mx/venues/la-merced/?lang=en', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'etiquette', 'Greet before the question', 'Open with buenos días or buenas tardes and use disculpe before asking a stranger for help. Usted is the respectful default with an unfamiliar adult; let the other person invite a more informal tone.', null, '🙏', null, '{"source": "https://mexicocity.cdmx.gob.mx/e/basics-for-mexico-city-travel/?lang=en"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://mexicocity.cdmx.gob.mx/e/basics-for-mexico-city-travel/?lang=en', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'etiquette', 'Confirm the Metro entrance before entering', 'In Mexico City, ask which Metro entrance and direction you need before passing the turnstile. Move out of the pedestrian stream while checking the map, and repeat the station or terminal name to confirm what you heard.', null, '🚌', null, '{"source": "https://mexicocity.cdmx.gob.mx/e/basics-for-mexico-city-travel/?lang=en"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://mexicocity.cdmx.gob.mx/e/basics-for-mexico-city-travel/?lang=en', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'etiquette', 'Ask about an atole', 'Ask how an atole is made here, especially when caffeine, dairy, sugar, or alcohol matters. In Mexico City it commonly accompanies tamales; ask which flavor is in the pot.', null, '🥤', null, '{"source": "https://www.gob.mx/inpi/articulos/el-atole-bebidas-tradicionales-de-los-pueblos-indigenas"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.gob.mx/inpi/articulos/el-atole-bebidas-tradicionales-de-los-pueblos-indigenas', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'etiquette', 'Share the space', 'Treat La Merced as a working public space: leave entrances open and ask before close-range photos. La Merced is a vast commercial district as well as a market complex, with food, household goods, flowers, and wholesale trade moving at working-city speed.', null, '🧺', null, '{"source": "https://mexicocity.cdmx.gob.mx/venues/la-merced/?lang=en"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://mexicocity.cdmx.gob.mx/venues/la-merced/?lang=en', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'mexico-city', 'market', 'La Merced', 'La Merced is a vast commercial district as well as a market complex, with food, household goods, flowers, and wholesale trade moving at working-city speed. Keep valuables secure, ask before photographing vendors, and visit to observe supply chains rather than hunt for a staged souvenir.', null, '🌶️', null, '{"source": "https://mexicocity.cdmx.gob.mx/venues/la-merced/?lang=en"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://mexicocity.cdmx.gob.mx/venues/la-merced/?lang=en', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'miami', 'phrase', 'Buenos días', 'Use buenos días as a morning greeting before one concise question. The phrase is useful in many Miami settings, but a greeting does not assume the listener''s preferred language.', 'Pronunciation: BWEH-nohs DEE-ahs', '👋', null, '{"context_source": "https://historymiami.org/wp-content/uploads/FFP-Report-What-Makes-Miami-Miami.pdf", "source": "https://dle.rae.es/bueno"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Good morning", "intent": "greeting", "language": "Spanish", "original": "Buenos días", "pronunciation": "BWEH-nohs DEE-ahs", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use in the morning at a shop, café, or Calle Ocho beyond the postcard counter."}'::jsonb, 'https://dle.rae.es/bueno', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'miami', 'phrase', 'Gracias', 'Use gracias after directions, service, or a purchase. Add the reason only when it clarifies what you appreciated; one sincere word is enough.', 'Pronunciation: GRAH-syahs', '🙏', null, '{"context_source": "https://historymiami.org/wp-content/uploads/FFP-Report-What-Makes-Miami-Miami.pdf", "source": "https://dle.rae.es/gracias"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Thank you", "intent": "thanks", "language": "Spanish", "original": "Gracias", "pronunciation": "GRAH-syahs", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use after directions, service, or a short exchange."}'::jsonb, 'https://dle.rae.es/gracias', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'miami', 'phrase', 'Por favor', 'Add por favor to a clear request or order rather than offering it as a sentence by itself. A greeting opens the exchange; this phrase keeps the request courteous.', 'Pronunciation: por fah-VOR', '🤲', null, '{"context_source": "https://www.miamiandbeaches.com/neighborhoods/little-havana", "source": "https://dle.rae.es/favor"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Please", "intent": "please", "language": "Spanish", "original": "Por favor", "pronunciation": "por fah-VOR", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Add to a request or order."}'::jsonb, 'https://dle.rae.es/favor', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'miami', 'phrase', 'Disculpe, ¿me puede ayudar?', 'Use the respectful singular form to get attention before one brief request. Let the other person decide how much help they can offer, listen for the answer, and close with gracias.', 'Pronunciation: dees-KOOL-peh, meh PWEH-deh ah-yoo-DAR', '🙋', null, '{"context_source": "https://historymiami.org/wp-content/uploads/FFP-Report-What-Makes-Miami-Miami.pdf", "source": "https://dle.rae.es/disculpar"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Excuse me, can you help me?", "intent": "help_excuse", "language": "Spanish", "original": "Disculpe, ¿me puede ayudar?", "pronunciation": "dees-KOOL-peh, meh PWEH-deh ah-yoo-DAR", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use with an unfamiliar adult before showing a map or destination."}'::jsonb, 'https://dle.rae.es/disculpar', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'miami', 'phrase', 'Quisiera un cafecito, por favor', 'Use quisiera to frame a courteous request, then name the item and add por favor. Keep the menu item visible if pronunciation becomes a barrier.', 'Pronunciation: kee-SYEH-rah oon kah-feh-SEE-toh; por fah-VOR', '🥤', null, '{"context_source": "https://www.lonelyplanet.com/articles/cuban-coffee-in-miami", "source": "https://dle.rae.es/querer"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "I would like a cafecito, please", "intent": "ordering", "language": "Spanish", "original": "Quisiera un cafecito, por favor", "pronunciation": "kee-SYEH-rah oon kah-feh-SEE-toh; por fah-VOR", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use at a coffee window; then state sugar preferences if the counter offers a choice."}'::jsonb, 'https://dle.rae.es/querer', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'miami', 'phrase', '¿Dónde está la ventanita?', 'Use dónde está before the place you are seeking. Ask the full question, listen for a street or landmark, repeat it back, and close with gracias.', 'Pronunciation: DOHN-deh ehs-TAH lah vehn-tah-NEE-tah', '🧭', null, '{"context_source": "https://www.miamiandbeaches.com/neighborhoods/little-havana", "source": "https://dle.rae.es/d%C3%B3nde"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Where is the walk-up coffee window?", "intent": "navigation", "language": "Spanish", "original": "¿Dónde está la ventanita?", "pronunciation": "DOHN-deh ehs-TAH lah vehn-tah-NEE-tah", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use in a Cuban café when looking for the walk-up window."}'::jsonb, 'https://dle.rae.es/d%C3%B3nde', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'miami', 'drink', 'Cafecito', 'A cafecito is a small, strong Cuban-style espresso sweetened as it is brewed. A colada is a larger shared serving with tiny cups; do not assume the whole pour is one person''s drink.', null, '☕', null, '{"source": "https://www.lonelyplanet.com/articles/cuban-coffee-in-miami"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.lonelyplanet.com/articles/cuban-coffee-in-miami', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'miami', 'drink', 'A fruit batido at the window', 'At a Miami ventanita, a batido is a fruit-and-milk shake that can offer a cold nonalcoholic counterpoint to cafecito. Ask which fruit is available, whether it contains dairy, and how much sugar is added before choosing.', null, '🫖', null, '{"source": "https://www.miamiandbeaches.com/neighborhoods/little-havana"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.miamiandbeaches.com/neighborhoods/little-havana', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'miami', 'etiquette', 'Share the colada', 'When someone orders a colada at a ventanita, the small cups signal sharing. Accept one if offered, return the cup to the group, and let regulars conduct their conversations without treating the window as a staged performance.', null, '🤲', null, '{"source": "https://historymiami.org/wp-content/uploads/FFP-Report-What-Makes-Miami-Miami.pdf"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://historymiami.org/wp-content/uploads/FFP-Report-What-Makes-Miami-Miami.pdf', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'miami', 'etiquette', 'Let the ventanita keep moving', 'At a Miami ventanita, decide on the drink before reaching the window, keep the pickup space clear, and step aside after paying. The window is a compact working counter and social space, not a photo set.', null, '🚌', null, '{"source": "https://historymiami.org/wp-content/uploads/FFP-Report-What-Makes-Miami-Miami.pdf"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://historymiami.org/wp-content/uploads/FFP-Report-What-Makes-Miami-Miami.pdf', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'miami', 'etiquette', 'Ask about a cafecito', 'Treat a cafecito as a recipe, not a fixed formula; check ingredients before ordering. A colada is a larger shared serving with tiny cups; do not assume the whole pour is one person''s drink.', null, '🥤', null, '{"source": "https://www.lonelyplanet.com/articles/cuban-coffee-in-miami"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.lonelyplanet.com/articles/cuban-coffee-in-miami', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'miami', 'etiquette', 'Share the space', 'At Calle Ocho beyond the postcard, finish purchases away from the queue and keep walkways open. Little Havana''s Calle Ocho mixes Cuban restaurants, ventanitas, galleries, memorials, music, and businesses serving a living neighborhood.', null, '🧺', null, '{"source": "https://www.miamiandbeaches.com/neighborhoods/little-havana"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.miamiandbeaches.com/neighborhoods/little-havana', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'miami', 'market', 'Calle Ocho beyond the postcard', 'Little Havana''s Calle Ocho mixes Cuban restaurants, ventanitas, galleries, memorials, music, and businesses serving a living neighborhood. Walk beyond one landmark, spend with local merchants, and recognize the wider Latin American and Caribbean city around it.', null, '🎶', null, '{"source": "https://www.miamiandbeaches.com/neighborhoods/little-havana"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.miamiandbeaches.com/neighborhoods/little-havana', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'milan', 'phrase', 'Buongiorno', '“Good morning / good day.” In Milan, use this when entering or beginning a daytime interaction.', 'Pronunciation: bwohn-JOR-noh', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Good morning / good day", "fact_review": "pending_human_review", "language": "Italian", "language_review": "pending_qualified_speaker_review", "original": "Buongiorno", "pronunciation": "bwohn-JOR-noh", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Italian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "when entering or beginning a daytime interaction", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Italian_phrasebook#Basics', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'milan', 'phrase', 'Grazie', '“Thank you.” In Milan, use this after service, directions, or assistance.', 'Pronunciation: GRAHT-see-eh', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Thank you", "fact_review": "pending_human_review", "language": "Italian", "language_review": "pending_qualified_speaker_review", "original": "Grazie", "pronunciation": "GRAHT-see-eh", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Italian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "after service, directions, or assistance", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Italian_phrasebook#Basics', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'milan', 'phrase', 'Per favore', 'Italian for “please,” useful in shops, cafés, stations, and any request. Pair it with buongiorno when beginning an interaction.', 'Pronunciation: pehr fah-VOH-reh', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Please", "fact_review": "pending_human_review", "language": "Italian", "language_review": "pending_qualified_speaker_review", "original": "Per favore", "pronunciation": "pehr fah-VOH-reh", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Italian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "Place it after a request; begin with buongiorno when approaching staff or strangers.", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Italian_phrasebook#Basics', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'milan', 'phrase', 'Mi scusi, può aiutarmi?', '“Excuse me, can you help me?” In Milan, use this before asking staff or a stranger for help.', 'Pronunciation: mee SKOO-zee, pwo ah-yoo-TAR-mee', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Excuse me, can you help me?", "fact_review": "pending_human_review", "language": "Italian", "language_review": "pending_qualified_speaker_review", "original": "Mi scusi, può aiutarmi?", "pronunciation": "mee SKOO-zee, pwo ah-yoo-TAR-mee", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Italian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before asking staff or a stranger for help", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Italian_phrasebook#Basics', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'milan', 'phrase', 'Vorrei…', '“I would like…” In Milan, use this before a menu item, quantity, or ticket.', 'Pronunciation: vor-RAY', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "I would like…", "fact_review": "pending_human_review", "language": "Italian", "language_review": "pending_qualified_speaker_review", "original": "Vorrei…", "pronunciation": "vor-RAY", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Italian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before a menu item, quantity, or ticket", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Italian_phrasebook#Basics', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'milan', 'phrase', 'Dov’è…?', '“Where is…?” In Milan, use this before a station, street, toilet, or landmark.', 'Pronunciation: doh-VEH', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Where is…?", "fact_review": "pending_human_review", "language": "Italian", "language_review": "pending_qualified_speaker_review", "original": "Dov’è…?", "pronunciation": "doh-VEH", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Italian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before a station, street, toilet, or landmark", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Italian_phrasebook#Basics', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'milan', 'drink', 'Chinotto', 'Chinotto is a bittersweet Italian carbonated soft drink flavored with citrus. It is usually alcohol-free and offers a grown-up alternative during aperitivo, but check the label.', 'Reference lead: Wikivoyage', '🍊', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "nonalcoholic": true, "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Eat", "source_title": "Milan travel guide: Eat", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Milan#Eat', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'milan', 'drink', 'Marocchino', 'Espresso layered with cocoa and a little milk foam is nonalcoholic but caffeinated; recipes vary, so ask about dairy and sweetness.', 'Reference lead: Wikivoyage', '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "nonalcoholic": true, "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Eat", "source_title": "Milan travel guide: Eat", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Milan#Eat', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'milan', 'etiquette', 'Aperitivo is not an obligation', 'Aperitivo is a pre-dinner social ritual, not a requirement to drink alcohol. Order a soft drink or alcohol-free aperitivo, and take only the food intended for your table.', 'Reference lead: Wikivoyage', '🍊', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Respect", "source_title": "Milan travel guide: Respect", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Milan#Respect', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'milan', 'etiquette', 'Share Metro, trams, buses, suburban rail, and busy station platforms', 'On Metro, trams, buses, suburban rail, and busy station platforms in Milan, let riders leave first, keep doors and aisles clear, and follow posted ticket or validation instructions; fare rules can change.', 'Reference lead: Wikivoyage', '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Get around", "source_title": "Milan travel guide: Get around", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Milan#Get_around', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'milan', 'etiquette', 'Browse Mercato Centrale Milano with care', 'At Mercato Centrale Milano, keep aisles open, ask before handling produce or photographing traders, and follow stall signs. Browsing should not interrupt Milan''s everyday shopping.', 'Reference lead: Wikivoyage', '🧺', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Buy", "source_title": "Milan travel guide: Buy", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Milan#Buy', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'milan', 'etiquette', 'Enter Milan Cathedral as a guest', 'At Milan Cathedral, follow posted rules, silence devices, and ask before photographing people or services. Its role as an active Catholic cathedral comes before a visitor''s photograph.', 'Reference lead: Wikivoyage', '🕯️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "See", "source_title": "Milan travel guide: See", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Milan#See', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'milan', 'market', 'Mercato Centrale Milano', 'Set within the Central Station complex, this market brings food artisans and prepared dishes into a major transport hub. Compare regional specialties, but keep passenger circulation and luggage paths clear.', 'Reference lead: Wikivoyage', '🚆', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Buy", "source_title": "Milan travel guide: Buy", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Milan#Buy', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'montreal', 'phrase', 'Bonjour', 'Use bonjour when approaching a counter, shop, or information desk, then make one concise request. The greeting works throughout the day; in the evening, bonsoir may be more natural.', 'Pronunciation: bohn-ZHOOR', '👋', null, '{"context_source": "https://www.mtl.org/en/experience/bonjour-montreal", "source": "https://nos-langues.canada.ca/fr/cles-de-la-redaction/bon-matin"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Hello", "intent": "greeting", "language": "French", "original": "Bonjour", "pronunciation": "bohn-ZHOOR", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use on entering a shop, café, or Marché Jean-Talon counter."}'::jsonb, 'https://nos-langues.canada.ca/fr/cles-de-la-redaction/bon-matin', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'montreal', 'phrase', 'Merci', 'A simple merci closes a short exchange without overstating your French. Beginning in French matters more than performing perfect pronunciation, and the same word works after directions, service, or a purchase.', 'Pronunciation: mehr-SEE', '🙏', null, '{"context_source": "https://www.mtl.org/en/experience/bonjour-montreal", "source": "https://www.larousse.fr/dictionnaires/francais/merci/50583"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Thank you", "intent": "thanks", "language": "French", "original": "Merci", "pronunciation": "mehr-SEE", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use after directions, service, or a brief exchange."}'::jsonb, 'https://www.larousse.fr/dictionnaires/francais/merci/50583', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'montreal', 'phrase', 'S''il vous plaît', 'Attach s''il vous plaît to a concise request or order when addressing an unfamiliar adult. The vous form keeps the register polite; a greeting should still come first.', 'Pronunciation: seel voo PLEH', '🤲', null, '{"context_source": "https://www.mtl.org/en/experience/public-markets-montreal", "source": "https://www.larousse.fr/dictionnaires/francais/plaire/61329"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Please", "intent": "please", "language": "French", "original": "S''il vous plaît", "pronunciation": "seel voo PLEH", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Add to a request or order."}'::jsonb, 'https://www.larousse.fr/dictionnaires/francais/plaire/61329', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'montreal', 'phrase', 'Excusez-moi, parlez-vous anglais ?', 'Ask this after bonjour when you need English; it gives the other person a clear choice instead of assuming a language. Keep the request brief, then continue in whichever language you both share.', 'Pronunciation: ehk-skew-zay MWAH, par-lay VOO ahn-GLAY', '🙋', null, '{"context_source": "https://www.mtl.org/en/experience/bonjour-montreal", "source": "https://www.larousse.fr/dictionnaires/guide/anglais"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Excuse me, do you speak English?", "intent": "help_excuse", "language": "French", "original": "Excusez-moi, parlez-vous anglais ?", "pronunciation": "ehk-skew-zay MWAH, par-lay VOO ahn-GLAY", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use after bonjour when you need to continue in English."}'::jsonb, 'https://www.larousse.fr/dictionnaires/guide/anglais', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'montreal', 'phrase', 'Je voudrais un allongé, s''il vous plaît', 'Use the complete request at a café, then clarify size, milk, sugar, or caffeine needs. Keep the menu item visible if pronunciation becomes a barrier.', 'Pronunciation: zhuh voo-DRAY uhn ah-lohn-ZHAY; seel voo PLEH', '🥤', null, '{"context_source": "https://www.mtl.org/en/experience/coffee-shops-montreal", "source": "https://www.larousse.fr/dictionnaires/guide/anglais"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "I would like an allongé, please", "intent": "ordering", "language": "French", "original": "Je voudrais un allongé, s''il vous plaît", "pronunciation": "zhuh voo-DRAY uhn ah-lohn-ZHAY; seel voo PLEH", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use at a café; then state milk or sugar preferences separately."}'::jsonb, 'https://www.larousse.fr/dictionnaires/guide/anglais', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'montreal', 'phrase', 'Où est le marché Jean-Talon ?', 'Say the full market name, then repeat the street or direction back to confirm it. The question asks for a location without implying that the other person should lead you there.', 'Pronunciation: oo EH luh mar-SHAY zhahn tah-LOHN', '🧭', null, '{"context_source": "https://www.mtl.org/en/experience/public-markets-montreal", "source": "https://www.larousse.fr/dictionnaires/guide/anglais"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "Where is Jean-Talon Market?", "intent": "navigation", "language": "French", "original": "Où est le marché Jean-Talon ?", "pronunciation": "oo EH luh mar-SHAY zhahn tah-LOHN", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_language_review", "usage": "Use when navigating toward Jean-Talon Market."}'::jsonb, 'https://www.larousse.fr/dictionnaires/guide/anglais', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'montreal', 'drink', 'An allongé at the counter', 'Montréal''s independent cafés range from Italian espresso counters to third-wave roasters. An allongé is espresso drawn longer with more water; pair it with a pastry and let the café be a pause rather than a fuel stop.', null, '☕', null, '{"source": "https://www.mtl.org/en/experience/coffee-shops-montreal"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.mtl.org/en/experience/coffee-shops-montreal', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'montreal', 'drink', 'Café au lait, taken slowly', 'Montréal''s café range makes a café au lait a useful second zero-proof order: coffee softened with hot milk. Ask about roast, milk, and cup size, then stay long enough to notice whether the room feels like an espresso counter or a neighborhood salon.', null, '🫖', null, '{"source": "https://www.mtl.org/en/experience/coffee-shops-montreal"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.mtl.org/en/experience/coffee-shops-montreal', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'montreal', 'etiquette', 'Start with bonjour', 'Open a shop, café, or information-desk exchange with bonjour before the request. If you need English, ask rather than launching straight into it; the small courtesy recognizes that French is the city''s public language.', null, '🤝', null, '{"source": "https://www.mtl.org/en/experience/bonjour-montreal"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.mtl.org/en/experience/bonjour-montreal', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'montreal', 'etiquette', 'Ask before switching to English', 'In Montréal, begin with bonjour and ask whether English is possible before changing languages. Keep the request brief and accept the answer without turning a routine service exchange into a debate about language.', null, '🚌', null, '{"source": "https://www.mtl.org/en/experience/bonjour-montreal"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.mtl.org/en/experience/bonjour-montreal', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'montreal', 'etiquette', 'Ask about an allongé', 'An allongé is espresso drawn longer with more water. Ask about caffeine, milk, and sweetness rather than assuming a house recipe, then let the café be a pause instead of a fuel stop.', null, '🥤', null, '{"source": "https://www.mtl.org/en/experience/coffee-shops-montreal"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.mtl.org/en/experience/coffee-shops-montreal', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'montreal', 'etiquette', 'Share the space', 'Treat Marché Jean-Talon as a working public space: leave entrances open and ask before close-range photos. Since 1933, Jean-Talon has brought growers, fishmongers, butchers, bakers, spice sellers, and Québec producers into one vivid public market.', null, '🧺', null, '{"source": "https://www.mtl.org/en/experience/public-markets-montreal"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.mtl.org/en/experience/public-markets-montreal', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'montreal', 'market', 'Marché Jean-Talon', 'Since 1933, Jean-Talon has brought growers, fishmongers, butchers, bakers, spice sellers, and Québec producers into one vivid public market. Taste seasonally, ask before photographing people at work, and leave room for Little Italy around it.', null, '🍎', null, '{"source": "https://www.mtl.org/en/experience/public-markets-montreal"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.mtl.org/en/experience/public-markets-montreal', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'moscow', 'phrase', 'Здравствуйте', '“Hello.” In Moscow, use this as a polite greeting to an adult or group.', 'Pronunciation: ZDRAST-vuy-tye', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Hello", "fact_review": "pending_human_review", "language": "Russian", "language_review": "pending_qualified_speaker_review", "original": "Здравствуйте", "pronunciation": "ZDRAST-vuy-tye", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Russian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "as a polite greeting to an adult or group", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Russian_phrasebook#Basics', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'moscow', 'phrase', 'Спасибо', 'Russian for “thank you,” written in Cyrillic. It is useful in every service interaction and after receiving directions or help.', 'Pronunciation: spa-SEE-ba', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Thank you", "fact_review": "pending_human_review", "language": "Russian", "language_review": "pending_qualified_speaker_review", "original": "Спасибо", "pronunciation": "spa-SEE-ba", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Russian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "Use after purchases, directions, or assistance; stress the middle syllable.", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Russian_phrasebook#Basics', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'moscow', 'phrase', 'Пожалуйста', '“Please / you''re welcome.” In Moscow, use this for requests and responses to thanks.', 'Pronunciation: pa-ZHAH-luh-sta', '🤝', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Please / you''re welcome", "fact_review": "pending_human_review", "language": "Russian", "language_review": "pending_qualified_speaker_review", "original": "Пожалуйста", "pronunciation": "pa-ZHAH-luh-sta", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Russian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "for requests and responses to thanks", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Russian_phrasebook#Basics', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'moscow', 'phrase', 'Извините, вы можете помочь?', '“Excuse me, can you help?” In Moscow, use this before asking staff or a stranger for help.', 'Pronunciation: eez-vee-NEE-tye, vy MOH-zhy-tye pah-MOCH', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Excuse me, can you help?", "fact_review": "pending_human_review", "language": "Russian", "language_review": "pending_qualified_speaker_review", "original": "Извините, вы можете помочь?", "pronunciation": "eez-vee-NEE-tye, vy MOH-zhy-tye pah-MOCH", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Russian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before asking staff or a stranger for help", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Russian_phrasebook#Basics', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'moscow', 'phrase', 'Можно, пожалуйста…?', '“May I have…, please?” In Moscow, use this before a menu item, ticket, or quantity.', 'Pronunciation: MOZH-nah, pa-ZHAH-luh-sta', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "May I have…, please?", "fact_review": "pending_human_review", "language": "Russian", "language_review": "pending_qualified_speaker_review", "original": "Можно, пожалуйста…?", "pronunciation": "MOZH-nah, pa-ZHAH-luh-sta", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Russian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before a menu item, ticket, or quantity", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Russian_phrasebook#Basics', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'moscow', 'phrase', 'Где находится…?', '“Where is…?” In Moscow, use this before a station, street, toilet, or landmark.', 'Pronunciation: gdyeh na-HO-deet-sya', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Where is…?", "fact_review": "pending_human_review", "language": "Russian", "language_review": "pending_qualified_speaker_review", "original": "Где находится…?", "pronunciation": "gdyeh na-HO-deet-sya", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Russian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before a station, street, toilet, or landmark", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Russian_phrasebook#Basics', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'moscow', 'drink', 'Морс', 'Mors is a tart berry drink made from fruit, water, and sugar, often using cranberry or lingonberry. It is generally alcohol-free and may be served warm or cold.', 'Reference lead: Wikivoyage', '🫐', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "nonalcoholic": true, "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Eat", "source_title": "Moscow travel guide: Eat", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moscow#Eat', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'moscow', 'drink', 'Безалкогольный сбитень', 'A nonalcoholic version of sbiten blends hot water, honey, and spices; confirm explicitly that no wine or spirits were added because recipes vary.', 'Reference lead: Wikivoyage', '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "nonalcoholic": true, "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Eat", "source_title": "Moscow travel guide: Eat", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moscow#Eat', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'moscow', 'etiquette', 'The Metro keeps a fast rhythm', 'Stand back from the platform edge, leave space at carriage doors for riders to exit, do not board after the closing signal, and keep clear of doors inside the train. Follow signs and staff directions as crowds change.', 'Reference lead: Wikivoyage', '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Get around", "source_title": "Moscow travel guide: Get around", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moscow#Get_around', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'moscow', 'etiquette', 'Browse Danilovsky Market with care', 'At Danilovsky Market, keep aisles open, ask before handling produce or photographing traders, and follow stall signs. Browsing should not interrupt Moscow''s everyday shopping.', 'Reference lead: Wikivoyage', '🧺', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Buy", "source_title": "Moscow travel guide: Buy", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moscow#Buy', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'moscow', 'etiquette', 'Enter Cathedral of Christ the Saviour as a guest', 'At Cathedral of Christ the Saviour, follow posted rules, silence devices, and ask before photographing people or services. Its role as an active Russian Orthodox cathedral comes before a visitor''s photograph.', 'Reference lead: Wikivoyage', '🕯️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "See", "source_title": "Moscow travel guide: See", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moscow#See', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'moscow', 'etiquette', 'Arbat is a neighborhood', 'In Arbat, keep doorways clear, lower late-night voices, and use public viewpoints rather than residential windows or courtyards. Moscow remains lived-in beyond its landmarks.', 'Reference lead: Wikivoyage', '🏘️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Respect", "source_title": "Moscow travel guide: Respect", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moscow#Respect', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'moscow', 'market', 'Danilovsky Market', 'A circular late-Soviet market building now combines produce, spices, pantry goods, and prepared food from Russia and neighboring regions. Read it as both architecture and contemporary food exchange.', 'Reference lead: Wikivoyage', '🥬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Buy", "source_title": "Moscow travel guide: Buy", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Moscow#Buy', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'phrase', 'NJ Transit', 'NJ Transit provides the regional bus links that connect Mount Laurel with nearby hubs. Say the agency name and route number; suburban stop patterns can differ by direction and time, so confirm the exact stop before boarding.', 'Pronunciation: en-jay transit', '🚌', null, '{"source": "https://www.njtransit.com/ride-bus"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "New Jersey''s statewide public-transit agency", "intent": "navigation_or_local_term", "language": "English", "original": "NJ Transit", "pronunciation": "en-jay transit", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "transliteration": null, "usage": "Ask for the route number and exact stop serving Mount Laurel or a transfer hub."}'::jsonb, 'https://www.njtransit.com/ride-bus', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'phrase', 'Hello—could you help me?', 'Begin with hello at Rancocas Woods, keep the question specific, and listen fully. Rancocas Woods Village Shops center independent crafters and antique dealers in a small Mount Laurel shopping district.', 'Pronunciation: spoken as written', '👋', null, '{"source": "https://visitsouthjersey.com/directory/rancocas-woods-village-shops/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "A polite greeting followed by a request for help", "intent": "greeting", "language": "English", "original": "Hello—could you help me?", "pronunciation": "spoken as written", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "usage": "Open with this before asking a vendor at Rancocas Woods a question."}'::jsonb, 'https://visitsouthjersey.com/directory/rancocas-woods-village-shops/', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'phrase', 'Thanks, I appreciate it', 'After help with NJ Transit, repeat the direction you understood and close with the full thank-you. NJ Transit provides the regional bus links that connect Mount Laurel with nearby hubs.', 'Pronunciation: spoken as written', '🙏', null, '{"source": "https://www.njtransit.com/ride-bus"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "A warm thank-you", "intent": "thanks", "language": "English", "original": "Thanks, I appreciate it", "pronunciation": "spoken as written", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "usage": "Use after someone explains NJ Transit, a route, or a local custom."}'::jsonb, 'https://www.njtransit.com/ride-bus', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'phrase', 'Please, when you have a moment', 'At Rancocas Woods, use this before a nonurgent question and wait for a pause. Browse slowly, support makers directly, and distinguish permanent shops from any seasonal market or event schedule.', 'Pronunciation: spoken as written', '⏳', null, '{"source": "https://visitsouthjersey.com/directory/rancocas-woods-village-shops/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "A request that respects the other person''s pace", "intent": "please", "language": "English", "original": "Please, when you have a moment", "pronunciation": "spoken as written", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "usage": "Use at a busy Rancocas Woods counter before a non-urgent question."}'::jsonb, 'https://visitsouthjersey.com/directory/rancocas-woods-village-shops/', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'phrase', 'Excuse me—could you help me?', 'Use this away from the doors, then identify NJ Transit and one destination. Say the agency name and route number; suburban stop patterns can differ by direction and time, so confirm the exact stop before boarding.', 'Pronunciation: spoken as written', '🙋', null, '{"source": "https://www.njtransit.com/ride-bus"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "A polite way to get attention and request help", "intent": "help_excuse", "language": "English", "original": "Excuse me—could you help me?", "pronunciation": "spoken as written", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "usage": "Use before asking which NJ Transit service or direction you need."}'::jsonb, 'https://www.njtransit.com/ride-bus', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'phrase', 'Could I have a cranberry spritz, please?', 'Ask how the house prepares it before naming dairy, sugar, or caffeine needs. New Jersey is one of the country''s leading cranberry-producing states, much of it in the nearby Pine Barrens region.', 'Pronunciation: spoken as written', '🥤', null, '{"source": "https://www.nj.gov/agriculture/news/press/2019/press191028.shtml"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "english": "A polite order for a cranberry spritz", "intent": "ordering", "language": "English", "original": "Could I have a cranberry spritz, please?", "pronunciation": "spoken as written", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review", "usage": "Use at the counter, then state zero-proof, sweetness, dairy, or caffeine needs plainly."}'::jsonb, 'https://www.nj.gov/agriculture/news/press/2019/press191028.shtml', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'drink', 'Garden State cranberry spritz', 'New Jersey is one of the country''s leading cranberry-producing states, much of it in the nearby Pine Barrens region. Cranberry juice cut with seltzer makes a tart nonalcoholic regional order without pretending it is a fixed historic recipe.', null, '🔴', null, '{"source": "https://www.nj.gov/agriculture/news/press/2019/press191028.shtml"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.nj.gov/agriculture/news/press/2019/press191028.shtml', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'drink', 'A Rancocas Woods cider pause', 'When a Rancocas Woods shop or seasonal vendor offers apple cider, ask whether it is hot or cold, sweetened, and fully nonalcoholic. Treat availability as seasonal and verify it on the day rather than assuming a village event schedule.', null, '🫖', null, '{"source": "https://visitsouthjersey.com/directory/rancocas-woods-village-shops/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://visitsouthjersey.com/directory/rancocas-woods-village-shops/', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'etiquette', 'Protect the Pinelands edge', 'Stay on marked paths, carry out litter, keep fire only where permitted, and never collect plants from protected land. Mount Laurel sits beside a region whose sandy soils, wetlands, and rare species are easily damaged.', null, '🌲', null, '{"source": "https://www.nj.gov/pinelands/about/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.nj.gov/pinelands/about/', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'etiquette', 'Confirm NJ Transit before boarding', 'Let riders exit NJ Transit, then confirm the line and direction away from the doors. NJ Transit provides the regional bus links that connect Mount Laurel with nearby hubs.', null, '🚌', null, '{"source": "https://www.njtransit.com/ride-bus"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.njtransit.com/ride-bus', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'etiquette', 'Ask about a cranberry spritz', 'Ask how a cranberry spritz is prepared and name any caffeine, dairy, sugar, or zero-proof needs. Cranberry juice cut with seltzer makes a tart nonalcoholic regional order without pretending it is a fixed historic recipe.', null, '🥤', null, '{"source": "https://www.nj.gov/agriculture/news/press/2019/press191028.shtml"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://www.nj.gov/agriculture/news/press/2019/press191028.shtml', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'etiquette', 'Share the space', 'Treat Rancocas Woods as a working public space: leave entrances open and ask before close-range photos. Rancocas Woods Village Shops center independent crafters and antique dealers in a small Mount Laurel shopping district.', null, '🧺', null, '{"source": "https://visitsouthjersey.com/directory/rancocas-woods-village-shops/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://visitsouthjersey.com/directory/rancocas-woods-village-shops/', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'market', 'Rancocas Woods', 'Rancocas Woods Village Shops center independent crafters and antique dealers in a small Mount Laurel shopping district. Browse slowly, support makers directly, and distinguish permanent shops from any seasonal market or event schedule.', null, '🪵', null, '{"source": "https://visitsouthjersey.com/directory/rancocas-woods-village-shops/"}'::jsonb, '{"accessed": "2026-07-25", "confidence": "medium", "recheck_status": "recheck_before_promotion", "research_attribution": "Automated Lore editorial research", "review_status": "pending_human_editorial_review"}'::jsonb, 'https://visitsouthjersey.com/directory/rancocas-woods-village-shops/', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'phrase', '... कुठे आहे? · ... kuṭhe āhe?', '“... kuṭhe āhe?” means “Where is ...?” Put the destination first or show its written name.', 'Pronunciation: koo-thay aa-hay', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Where is ...?", "fact_review": "pending_human_fact_review", "intent": "navigation", "language": "Marathi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "... कुठे आहे?", "pronunciation": "koo-thay aa-hay", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "... kuṭhe āhe?", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Put the destination first or show its written name.", "usage_context": "Put the destination first or show its written name.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/marathi.php', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'phrase', 'कृपया · kr̥payā', '“kr̥payā” means “Please.” Add it to a courteous request.', 'Pronunciation: krip-yaa', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Please", "fact_review": "pending_human_fact_review", "intent": "please", "language": "Marathi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "कृपया", "pronunciation": "krip-yaa", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "kr̥payā", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Add it to a courteous request.", "usage_context": "Add it to a courteous request.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/marathi.php', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'phrase', 'धन्यवाद · Dhanyavād', '“Dhanyavād” is a respectful Marathi “thank you.” Mumbai is multilingual, with Marathi, Hindi, Urdu, Gujarati, English, and many other languages in daily life, so use the phrase as courtesy while following the other person’s lead.', 'Pronunciation: dhanyavād', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Thank you", "fact_review": "pending_human_fact_review", "intent": "thanks", "language": "Marathi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "धन्यवाद", "pronunciation": "dhanyavād", "recheck_date": "2027-01-25", "register": "respectful", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "dhanyavād", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Express respectful thanks after help, service, or directions.", "usage_context": "Useful across everyday encounters; Mumbai is multilingual, so adapt graciously to the language used in reply.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/marathi.php', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'phrase', 'नमस्कार · namaskār', '“namaskār” means “Hello.” Offer this respectful Marathi greeting once, then follow the language the other person uses back.', 'Pronunciation: nuh-muh-skaar', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Hello", "fact_review": "pending_human_fact_review", "intent": "greeting", "language": "Marathi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "नमस्कार", "pronunciation": "nuh-muh-skaar", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "namaskār", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "A respectful everyday greeting in Marathi.", "usage_context": "A respectful everyday greeting in Marathi.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/marathi.php', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'phrase', 'मला हे हवे आहे · malā he have āhe', '“malā he have āhe” means “I would like this.” Use it with a menu item or a clear point.', 'Pronunciation: muh-laa hay huh-vay aa-hay', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "I would like this", "fact_review": "pending_human_fact_review", "intent": "ordering", "language": "Marathi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "मला हे हवे आहे", "pronunciation": "muh-laa hay huh-vay aa-hay", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "malā he have āhe", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it with a menu item or a clear point.", "usage_context": "Use it with a menu item or a clear point.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/marathi.php', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'phrase', 'माफ करा · māf karā', '“māf karā” means “Excuse me; sorry.” Use it to apologize lightly or get attention.', 'Pronunciation: maaf kuh-raa', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "english": "Excuse me; sorry", "fact_review": "pending_human_fact_review", "intent": "excuse", "language": "Marathi", "language_reviewer": "pending_qualified_speaker_review", "original_script": "माफ करा", "pronunciation": "maaf kuh-raa", "recheck_date": "2027-01-25", "register": "polite", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "review_status": "pending_qualified_speaker_review", "romanization": "māf karā", "source_publisher": "omniglot.com", "source_title": "Direct traveler-language reference", "translation_reviewer": "pending_qualified_speaker_review", "usage": "Use it to apologize lightly or get attention.", "usage_context": "Use it to apologize lightly or get attention.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.omniglot.com/language/phrases/marathi.php', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'drink', 'Irani chai: a café table in one cup', 'Mumbai''s Irani cafés serve strong tea with extra milk and spice, often beside brun maska. It is nonalcoholic and caffeinated; sweetness can be substantial, so ask before ordering if you prefer less sugar.', null, '🫖', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Usually dairy, sweetened, and caffeinated.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Mumbai''s Irani and Parsi cafés", "source_publisher": "dsource.in", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://dsource.in/resource/irani-cafes-bombay/popular-offerings-cafe', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'drink', 'Sol kadhi: kokum and coconut', 'Sol kadhi combines tart kokum with coconut milk for a pink, savory drink often paired with coastal food. It is nonalcoholic; garlic, chile, salt, and dairy-free preparation vary by kitchen.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "alcoholic": false, "confidence": "qualified", "dietary_note": "Usually coconut-based; spice and garlic vary.", "fact_review": "pending_human_fact_review", "nonalcoholic": true, "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Food and drink in Mumbai", "source_publisher": "maharashtratourism.gov.in", "source_title": "Local food and drink reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://maharashtratourism.gov.in/flavors-of-maharashtra/', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'etiquette', 'Railway concourses are not portrait studios', 'Railway concourses are transport infrastructure, not portrait studios. Stay behind safety markings, keep moving routes clear, and ask workers or passengers before making them the subject.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "photography and shared-space courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "working railway concourses", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/maharashtra/mumbai', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'etiquette', 'Ask the counter''s rhythm at Crawford Market counters', 'At Crawford Market, produce, spices, pets, and household goods use different sellers. Confirm quantity and total before paying, and do not block handcarts while deciding.', null, '🧾', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "ordering, queue, and payment courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Crawford Market counters", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/maharashtra/mumbai', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'etiquette', 'Make space on Mumbai local and metro platforms', 'Mumbai''s suburban rail and metro systems differ. Follow platform signs, never board a moving train, and wait for a less crowded car rather than forcing entry.', null, '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "transit and queue courtesy", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Mumbai local and metro platforms", "source_publisher": "mmrcl.com", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.mmrcl.com/', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'etiquette', 'Shoes, photos, and silence are site-specific', 'Mumbai’s temples, mosques, churches, synagogues, and dargahs each set their own visitor expectations. Follow posted shoe, dress, entry, and photography rules; ask a steward when unsure and never interrupt prayer for a better view.', null, '🕊️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "cultural_safety_review": "pending_human_cultural_safety_review", "fact_review": "pending_human_fact_review", "guidance_type": "site-specific respectful conduct", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Active places of worship", "source_publisher": "incredibleindia.gov.in", "source_title": "Official visitor conduct reference", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/faqs', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'mumbai', 'market', 'Crawford Market: city pantry in motion', 'Crawford Market and its surrounding lanes connect produce, spices, household goods, and Mumbai’s layered food culture. Treat it as a working market: watch for handcarts, avoid blocking transactions, and ask before photographing vendors or animals.', null, '🥭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "qualified", "fact_review": "pending_human_fact_review", "mutable_details_excluded": true, "operation_recheck": "2027-01-25", "recheck_date": "2027-01-25", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "setting": "Historic working market district", "source_publisher": "incredibleindia.gov.in", "source_title": "Official destination market guide", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.incredibleindia.gov.in/en/maharashtra/mumbai', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'munich', 'phrase', 'Servus', 'Servus is an informal greeting and farewell heard in Bavaria and Austria. Use it in relaxed settings; Guten Tag is safer when formality is unclear.', 'Pronunciation: SEHR-voos', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Hello / goodbye", "fact_review": "pending_human_review", "language": "German", "language_review": "pending_qualified_speaker_review", "original": "Servus", "pronunciation": "SEHR-voos", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "German phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "Use informally in Bavaria; choose Guten Tag for formal or first-time professional interactions.", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/German_phrasebook#Basics', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'munich', 'phrase', 'Danke', '“Thank you.” In Munich, use this after service or assistance.', 'Pronunciation: DAHN-kuh', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Thank you", "fact_review": "pending_human_review", "language": "German", "language_review": "pending_qualified_speaker_review", "original": "Danke", "pronunciation": "DAHN-kuh", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "German phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "after service or assistance", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/German_phrasebook#Basics', 'cc0', 121, 'reference_only'),
