(gen_random_uuid(), 'munich', 'phrase', 'Entschuldigung, können Sie helfen?', '“Excuse me, can you help?” In Munich, use this before asking a stranger or staff member for help.', 'Pronunciation: ent-SHOOL-dee-goong, KUR-nen zee HEL-fen', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Excuse me, can you help?", "fact_review": "pending_human_review", "language": "German", "language_review": "pending_qualified_speaker_review", "original": "Entschuldigung, können Sie helfen?", "pronunciation": "ent-SHOOL-dee-goong, KUR-nen zee HEL-fen", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "German phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before asking a stranger or staff member for help", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/German_phrasebook#Basics', 'cc0', 123, 'reference_only'),
