(gen_random_uuid(), 'oslo', 'phrase', 'Takk', 'Norwegian for “thank you,” compact and useful everywhere. Tusen takk adds warmth and literally means “a thousand thanks.”', 'Pronunciation: tahk', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Thank you", "fact_review": "pending_human_review", "language": "Norwegian Bokmål", "language_review": "pending_qualified_speaker_review", "original": "Takk", "pronunciation": "tahk", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Norwegian Bokmål phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "Use in all everyday settings; say tusen takk for stronger appreciation.", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Norwegian_phrasebook#Basics', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'oslo', 'phrase', 'Vær så snill', '“Please.” In Oslo, use this for a courteous request.', 'Pronunciation: vair soh snil', '🤝', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Please", "fact_review": "pending_human_review", "language": "Norwegian Bokmål", "language_review": "pending_qualified_speaker_review", "original": "Vær så snill", "pronunciation": "vair soh snil", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Norwegian Bokmål phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "for a courteous request", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Norwegian_phrasebook#Basics', 'cc0', 122, 'reference_only'),
