(gen_random_uuid(), 'rome', 'phrase', 'Mi scusi', 'A polite Italian “excuse me” for asking directions, approaching staff, or moving through a crowd. Scusa is the informal version.', 'Pronunciation: mee SKOO-zee', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Excuse me", "fact_review": "pending_human_review", "language": "Italian", "language_review": "pending_qualified_speaker_review", "original": "Mi scusi", "pronunciation": "mee SKOO-zee", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Italian phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "Use with staff and strangers; use scusa with friends or in clearly informal settings.", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Italian_phrasebook#Basics', 'cc0', 123, 'reference_only'),
