(gen_random_uuid(), 'stockholm', 'phrase', 'Ursäkta, kan du hjälpa mig?', '“Excuse me, can you help me?” In Stockholm, use this before asking for help.', 'Pronunciation: OOR-shek-tah, kan doo YEL-pah may', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Excuse me, can you help me?", "fact_review": "pending_human_review", "language": "Swedish", "language_review": "pending_qualified_speaker_review", "original": "Ursäkta, kan du hjälpa mig?", "pronunciation": "OOR-shek-tah, kan doo YEL-pah may", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Swedish phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before asking for help", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Swedish_phrasebook#Basics', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'stockholm', 'phrase', 'Jag skulle vilja ha…', '“I would like…” In Stockholm, use this before a menu item, ticket, or quantity.', 'Pronunciation: yah SKOOL-leh VIL-yah hah', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "I would like…", "fact_review": "pending_human_review", "language": "Swedish", "language_review": "pending_qualified_speaker_review", "original": "Jag skulle vilja ha…", "pronunciation": "yah SKOOL-leh VIL-yah hah", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Swedish phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before a menu item, ticket, or quantity", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Swedish_phrasebook#Basics', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'stockholm', 'phrase', 'Var ligger…?', '“Where is…?” In Stockholm, use this before a station, street, toilet, or landmark.', 'Pronunciation: vahr LIG-er', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "english": "Where is…?", "fact_review": "pending_human_review", "language": "Swedish", "language_review": "pending_qualified_speaker_review", "original": "Var ligger…?", "pronunciation": "vahr LIG-er", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "register_review": "pending_qualified_speaker_review", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Basics", "source_title": "Swedish phrasebook: basics", "translation_review": "pending_qualified_speaker_review", "usage": "before a station, street, toilet, or landmark", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Swedish_phrasebook#Basics', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'stockholm', 'drink', 'Lingondricka', 'Lingonberry drink balances tart berries with water and sweetness. It is alcohol-free and pairs naturally with Swedish home-style meals, though recipes vary.', 'Reference lead: Wikivoyage', '🫐', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "nonalcoholic": true, "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Eat", "source_title": "Stockholm travel guide: Eat", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Stockholm#Eat', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'stockholm', 'drink', 'Bryggkaffe', 'Swedish filter coffee is a straightforward, nonalcoholic but caffeinated fika drink; ask for a smaller cup, milk, or decaf when needed.', 'Reference lead: Wikivoyage', '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "nonalcoholic": true, "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Eat", "source_title": "Stockholm travel guide: Eat", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Stockholm#Eat', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'stockholm', 'etiquette', 'Fika makes space for conversation', 'Fika is a social coffee break, not simply a pastry purchase. If invited, allow time to talk; coffee can always be replaced with tea or another alcohol-free drink.', 'Reference lead: Wikivoyage', '☕', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Respect", "source_title": "Stockholm travel guide: Respect", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Stockholm#Respect', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'stockholm', 'etiquette', 'Share Metro, buses, commuter rail, trams, ferries, and escalators', 'On Metro, buses, commuter rail, trams, ferries, and escalators in Stockholm, let riders leave first, keep doors and aisles clear, and follow posted ticket or validation instructions; fare rules can change.', 'Reference lead: Wikivoyage', '🚇', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Get around", "source_title": "Stockholm travel guide: Get around", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Stockholm#Get_around', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'stockholm', 'etiquette', 'Browse Östermalms Saluhall with care', 'At Östermalms Saluhall, keep aisles open, ask before handling produce or photographing traders, and follow stall signs. Browsing should not interrupt Stockholm''s everyday shopping.', 'Reference lead: Wikivoyage', '🧺', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Buy", "source_title": "Stockholm travel guide: Buy", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Stockholm#Buy', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'stockholm', 'etiquette', 'Enter Stockholm Cathedral as a guest', 'At Stockholm Cathedral, follow posted rules, silence devices, and ask before photographing people or services. Its role as an active Lutheran cathedral comes before a visitor''s photograph.', 'Reference lead: Wikivoyage', '🕯️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "See", "source_title": "Stockholm travel guide: See", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Stockholm#See', 'cc0', 143, 'reference_only'),
(gen_random_uuid(), 'stockholm', 'market', 'Östermalms Saluhall', 'This historic food hall gathers fish, meat, cheese, bread, produce, and prepared dishes under a richly detailed roof. Treat it as one polished expression of Swedish food culture, not the only one.', 'Reference lead: Wikivoyage', '🐟', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "developing", "cultural_safety_review": "not_reviewed", "fact_review": "pending_human_review", "recheck_by": "2026-08-24", "recheck_state": "recheck_before_publication", "region": "Europe", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_fact_review", "source_author": "Wikivoyage contributors", "source_publication_date": "continuously updated", "source_publisher": "Wikivoyage", "source_section": "Buy", "source_title": "Stockholm travel guide: Buy", "wave": "2026-07", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Stockholm#Buy', 'cc0', 150, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'phrase', 'Tafadhali', 'Tafadhali (tah-fah-DHAH-lee) means "please" in Swahili. Use it when asking for directions, ordering, or requesting permission; pair it with a greeting and asante afterward so the phrase supports a courteous exchange rather than replacing one.', 'Pronunciation: tah-fah-DHAH-lee', '💬', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "Please", "language": "Swahili", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "tah-fah-DHAH-lee", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "transliteration": "tah-fah-DHAH-lee", "usage": "Tafadhali (tah-fah-DHAH-lee) means \"please\" in Swahili. Use it when asking for directions, ordering, or requesting permission; pair it with a greeting and asante afterward so the phrase supports a courteous exchange rather than replacing one.", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Swahili_phrasebook', 'cc0', 120, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'phrase', 'Habari?', 'How are things? Use this greeting before a request and listen for the reply; Stone Town''s Swahili is lived language, not decoration.', 'Pronunciation: hah-BAH-ree', '👋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "english": "How are things?; hello", "language": "Swahili", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "hah-BAH-ree", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "An everyday greeting", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Swahili_phrasebook', 'cc0', 121, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'phrase', 'Asante', 'Thank you. Use it after directions, service, or a small kindness; add sana for very much.', 'Pronunciation: ah-SAHN-teh', '🙏', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Thank you", "language": "Swahili", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "ah-SAHN-teh", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Everyday thanks", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Swahili_phrasebook', 'cc0', 122, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'phrase', 'Samahani', 'Excuse me or sorry. Use it to pass in a narrow lane, get attention, or repair a minor mistake.', 'Pronunciation: sah-mah-HAH-nee', '🙋', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Excuse me; sorry", "language": "Swahili", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "sah-mah-HAH-nee", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "A minor apology or polite interruption", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Swahili_phrasebook', 'cc0', 123, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'phrase', 'Naomba...', 'May I have ...? Use it before a food, drink, or item, then confirm ingredients or quantity.', 'Pronunciation: nah-OHM-bah', '🍽️', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "May I have ...?", "language": "Swahili", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "nah-OHM-bah", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Ordering or requesting an item", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Swahili_phrasebook', 'cc0', 124, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'phrase', '...iko wapi?', 'Where is ...? Put the place first and use a known landmark to confirm the route through the lanes.', 'Pronunciation: ... EE-koh WAH-pee', '🧭', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "high", "english": "Where is ...?", "language": "Swahili", "language_review_state": "pending_qualified_speaker_review", "pronunciation": "... EE-koh WAH-pee", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "usage": "Finding a place or landmark", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Swahili_phrasebook', 'cc0', 125, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'drink', 'Sugarcane, Lime, and Ginger', 'Fresh sugarcane juice is an alcohol-free Stone Town refresher, often lifted with lime and ginger. Watch it pressed, drink it freshly made from a clean setup, and expect the sharpness and sweetness to shift with the cane and the hand making it.', null, '🥤', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://www.discoverzanzibar.net/index.php/to_book/darajani-market/', 'cc0', 130, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'drink', 'Chai ya Masala, Island Warmth', 'Spiced tea may combine black tea, milk, sugar, ginger, or masala. Ask how this cup is made and request less sugar or no milk if needed.', null, '🫖', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "nonalcoholic": true, "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://en.wikivoyage.org/wiki/Swahili_phrasebook', 'cc0', 131, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'etiquette', 'A World Heritage Town Is a Home', 'Stone Town is a living Swahili, Muslim, and mercantile city, not only a preserved facade. Dress modestly away from the beach, lower your voice near worship, ask before photographing residents, and never enter private courtyards or religious spaces without a clear invitation.', null, '🚪', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "research_attribution": "Automated Lore editorial research", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://zanzibar.org/cultural-etiquette/', 'cc0', 140, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'etiquette', 'Dress for a Lived Muslim Town', 'Cover shoulders and knees away from the beach, especially near mosques and during religious periods. Follow local signs rather than treating dress as costume.', null, '🧣', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://zanzibar.org/cultural-etiquette/', 'cc0', 141, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'etiquette', 'The Lane Belongs to Daily Life', 'Step aside for carts, bicycles, deliveries, and residents. Pause in a square or recess before checking your map instead of blocking a doorway.', null, '🚶', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://whc.unesco.org/en/list/173/', 'cc0', 142, 'reference_only'),
(gen_random_uuid(), 'stone-town', 'etiquette', 'Permission Before People or Doors', 'Ask before photographing a person, an open domestic doorway, or worship. Architectural interest never cancels a resident''s privacy or consent.', null, '📷', null, '{}'::jsonb, '{"accessed_date": "2026-07-25", "confidence": "medium", "cultural_safety_review_state": "pending_human_review", "recheck_state": "recheck_before_publication", "review_state": "pending_human_editorial_review", "writer": "Automated Lore editorial research"}'::jsonb, 'https://zanzibar.org/cultural-etiquette/', 'cc0', 143, 'reference_only'),
